// empire-glance.js - 'At a glance' takeaways, 'Did you know?' and key events per profile. Loaded only by generator.html.

var GLANCE = {
  "Abbasid Caliphate": {t:["The Abbasids overthrew the Umayyads in 750 and ruled a multi-ethnic Islamic empire from their new capital, Baghdad.","Baghdad's House of Wisdom translated Greek, Persian and Indian learning into Arabic and helped give the world algebra.","Turkic slave soldiers, then Buyid and Seljuk overlords, hollowed out caliphal power long before the Mongols sacked Baghdad in 1258."],dyk:"The word 'algebra' comes from al-jabr in the title of al-Khwarizmi's treatise on calculation, written in Abbasid Baghdad around 820.",ev:[["750","Abbasid rebels defeat the Umayyads at the Battle of the Great Zab"],["762","Al-Mansur founds the Round City of Baghdad on the Tigris"],["c. 820","Al-Khwarizmi writes the treatise that gives algebra its name"],["836","Al-Mu'tasim moves the capital to Samarra to house his Turkic slave army"],["861","Assassination of al-Mutawakkil begins the Anarchy at Samarra"],["945","The Buyids take Baghdad, leaving the caliphs only religious authority"],["1258","Hulagu Khan's Mongols sack Baghdad and execute Caliph al-Musta'sim"],["1517","Selim I conquers Egypt, ending the Mamluk-sponsored shadow caliphate in Cairo"]]},
  "Achaemenid Empire": {t:["The first Persian Empire, built by Cyrus the Great, stretched from the Indus to the Aegean and the Nile.","Darius I's satrapies, Royal Road, coinage and Aramaic chancery became the model for later Near Eastern empires.","Weakened by revolts and court murders, it fell to Alexander the Great in just four years, 334 to 330 BCE."],dyk:"Royal couriers on the 2,700-kilometre Royal Road from Susa to Sardis could cover the distance in around a week, using relays of fresh riders.",ev:[["550 BCE","Cyrus II defeats Astyages and takes over the Median Empire"],["539 BCE","Cyrus defeats the Babylonians at Opis and enters Babylon"],["525 BCE","Cambyses II defeats Psamtik III at Pelusium and conquers Egypt"],["480 BCE","Xerxes invades Greece, wins at Thermopylae, sacks Athens but loses at Salamis"],["404 BCE","Egypt revolts on the death of Darius II and stays independent for six decades"],["343 BCE","Artaxerxes III reconquers Egypt"],["331 BCE","Alexander the Great defeats Darius III at Gaugamela"],["330 BCE","Alexander burns Persepolis; Darius III is murdered by his satrap Bessus"]]},
  "Adal Sultanate": {t:["Adal was a Muslim sultanate of the Horn of Africa, rich from the port of Zeila and later ruled from Harar.","Under Imam Ahmad ibn Ibrahim, firearms helped it overrun much of the Ethiopian highlands between 1529 and 1543.","Ahmad's death at Wayna Daga, then Oromo migrations and Ethiopian victories, reduced Adal to remnant states by 1577."],dyk:"The Ethiopian-Adal War drew in both global rivals of the age: about 400 Portuguese musketeers fought for Ethiopia, while Ottoman musketeers fought for Adal.",ev:[["c. 1415","Sabr ad-Din III founds Adal after returning from exile in Yemen"],["1445","Sultan Badlay is defeated and killed by Zara Yaqob at the Battle of Gomit"],["1520","Sultan Abu Bakr moves the capital from Dakkar to Harar"],["1529","Imam Ahmad routs Lebna Dengel's larger Ethiopian army at Shimbra Kure"],["1543","Imam Ahmad is killed at Wayna Daga and his coalition collapses"],["1559","Nur ibn Mujahid kills Emperor Gelawdewos at the Battle of Fatagar"],["1576","Sarsa Dengel defeats Sultan Muhammad ibn Nasir at the Webi River"],["1577","The dynasty withdraws to the oasis of Aussa"]]},
  "Afsharid Empire": {t:["Nader Shah, a general from the Afshar tribe, expelled Iran's occupiers and crowned himself Shah in 1736.","His 1739 sack of Delhi crippled the Mughal Empire and brought the Peacock Throne and Koh-i-Noor to Persia.","Built on one man's military genius, the empire shattered within months of his assassination in 1747."],dyk:"The treasure Nader Shah took from Delhi in 1739 was so vast that he remitted taxes throughout Iran for three years.",ev:[["1729","Nader expels the Ghilzai Afghans from Isfahan after seven years of occupation"],["1736","Nader is proclaimed Shah after a great assembly on the Mughan plain"],["1739","Nader crushes a much larger Mughal army at Karnal and enters Delhi"],["1740","Nader campaigns in Central Asia, subduing Bukhara and Khiva"],["1742","Nader has his eldest son Reza Qoli blinded on suspicion of plotting"],["1745","Nader defeats the Ottomans at Kars"],["1747","Nader Shah is assassinated by his own officers near Quchan"],["1796","Agha Mohammad Khan Qajar takes Mashhad; Shahrokh dies, ending the dynasty"]]},
  "Akkadian Empire": {t:["Founded by Sargon of Akkad, it is widely regarded as the world's first empire, uniting the Sumerian city-states under one ruler.","Its governors, standard measures and written Akkadian set the template that later Mesopotamian empires followed.","Gutian raids, palace murders and a severe drought around 2200 BCE brought it down; its capital has never been found."],dyk:"Sargon's daughter Enheduanna, high priestess of the moon god at Ur, is often described as the first named author in recorded history.",ev:[["c. 2334 BCE","Sargon of Akkad founds the empire after supplanting King Ur-Zababa of Kish"],["c. 2254 BCE","Naram-Sin, Sargon's grandson, begins the reign that marks the empire's zenith"],["c. 2240 BCE","Akkadian power peaks under Naram-Sin, self-styled King of the Four Quarters"],["c. 2200 BCE","The 4.2-kiloyear drought brings crop failure and famine across the Near East"],["c. 2193 BCE","Shar-Kali-Sharri dies, leaving a chaotic succession of short-lived kings"],["c. 2154 BCE","The Akkadian dynasty comes to an end"]]},
  "Aksumite Empire": {t:["Aksum, in highland Ethiopia and Eritrea, grew rich trading African ivory and gold through its Red Sea port of Adulis.","Under King Ezana it became one of the first states to adopt Christianity, founding Ethiopia's Orthodox tradition.","Cut off from Red Sea trade by Persia and the early Islamic conquests, it shrank into a regional highland kingdom."],dyk:"Aksum was one of the very few ancient states to mint its own gold coins, and the first to place the Christian cross on its coinage.",ev:[["c. 270","King Endubis introduces Aksumite gold, silver and bronze coinage"],["c. 350","King Ezana conquers the Kingdom of Kush, reaching the Nile"],["c. 525","King Kaleb's seaborne expedition overthrows the Himyarite king Dhu Nuwas in Yemen"],["570s","A Sasanian force takes Yemen, cutting Aksum off from the Arabian trade"],["c. 615","Aksum shelters early Muslim emigrants from Arabia"],["Early 7th century","Aksumite coinage ceases after more than three centuries"]]},
  "Almohad Caliphate": {t:["A Berber religious reform movement from the Atlas Mountains that united the whole Maghreb and Muslim al-Andalus.","Its court patronised Averroes, whose Aristotle commentaries reshaped European scholastic thought.","Defeat at Las Navas de Tolosa in 1212 shattered its prestige; the Marinids took Marrakesh in 1269."],dyk:"Seville's Giralda, now the cathedral bell tower, was begun in 1184 as the minaret of the city's Almohad Great Mosque.",ev:[["1121","Ibn Tumart is proclaimed the Mahdi by his followers in the Atlas Mountains"],["1147","Abd al-Mu'min captures the Almoravid capital Marrakesh and takes the title of caliph"],["1160","Almohads complete the conquest of the Maghreb from Morocco to Tunisia"],["1172","Abu Yaqub Yusuf I absorbs the last independent Muslim principality of al-Andalus"],["1195","Yaqub al-Mansur crushes Alfonso VIII of Castile at the Battle of Alarcos"],["1212","Christian coalition shatters the Almohad army at Las Navas de Tolosa"],["1248","Ferdinand III of Castile takes Seville"],["1269","The last caliph, Idris al-Wathiq, is killed as the Marinids seize Marrakesh"]]},
  "Almoravid Empire": {t:["Saharan Berber reformists who built an empire from the Senegal River to the Ebro, ruled from Marrakesh.","Their victory at Sagrajas in 1086 halted Castile's advance and kept much of al-Andalus Muslim for generations.","Overstretched on two fronts, they fell to the Almohads, who used the same charge of impiety the Almoravids once used."],dyk:"The Almoravid gold dinar was so trusted that Christian Iberia imitated it as the morabetino, the origin of the Castilian maravedí.",ev:[["1054–1055","Almoravids capture Sijilmasa, northern terminus of the trans-Saharan gold trade"],["c. 1070","Marrakesh is founded as the capital of the northern branch"],["1086","Yusuf ibn Tashfin shatters Alfonso VI's army at the Battle of Sagrajas"],["1091","Almoravids absorb the taifa kingdom of Seville"],["1106","Death of Yusuf ibn Tashfin, the empire's greatest ruler"],["1118","Alfonso I of Aragon takes Zaragoza"],["1145","Tashfin ibn Ali dies near Oran, opening Morocco to the Almohads"],["1147","Almohads storm Marrakesh and kill the last Almoravid ruler, Ishaq ibn Ali"]]},
  "Ashanti Empire": {t:["Osei Tutu I united Akan chiefdoms in Ghana's forest zone around 1700, bound together by the sacred Golden Stool.","Rich in gold and kola, Asante resisted British expansion through five wars between 1824 and 1900.","Annexed by Britain in 1902, it never surrendered the Golden Stool, and its king is still recognised in Ghana today."],dyk:"No one sits on the Golden Stool: the Asantehene is enstooled beneath it, as it embodies the soul of the whole Asante nation.",ev:[["1701","Asante coalition defeats Denkyira at Feyiase, gaining access to coastal trade"],["1824","Asante army annihilates a British-led force at Nsamankow, killing Governor MacCarthy"],["1826","A British-led coalition aided by Congreve rockets defeats Asante at Katamansu"],["1831","Treaty of Peace fixes the River Pra as the southern limit of Asante influence"],["1874","Sir Garnet Wolseley's expedition enters Kumasi and burns the capital"],["1896","British occupy Kumasi without a fight and depose Asantehene Prempeh I"],["1900","Yaa Asantewaa leads the War of the Golden Stool against British rule"],["1902","Asante is formally annexed as a British crown colony"]]},
  "Assyrian Empire": {t:["From the city of Assur on the Tigris, Assyria grew from a merchant network into the largest empire the world had yet seen.","Its provinces, royal couriers, siege engineers and mass deportations became models for Babylon and Persia.","Overstretched and hated by its subjects, it was destroyed by Medes and Babylonians in barely sixty years after its peak."],dyk:"The Library of Ashurbanipal at Nineveh preserved the standard version of the Epic of Gilgamesh, one of the oldest surviving works of literature.",ev:[["c. 2025 BCE","Assur emerges as an independent city-state after the fall of the Third Dynasty of Ur"],["c. 1225 BCE","Tukulti-Ninurta I conquers Babylon and captures its Kassite king"],["911 BCE","Adad-nirari II launches the Neo-Assyrian revival"],["745 BCE","Tiglath-pileser III takes the throne and reorganises army and provinces"],["722 BCE","Samaria falls and the population of the Kingdom of Israel is deported"],["671 BCE","Esarhaddon conquers Egypt, bringing the empire to its greatest extent"],["612 BCE","Babylonians and Medes destroy the Assyrian capital Nineveh"],["609 BCE","Ashur-uballit II fails to retake Harran and vanishes from the record"]]},
  "Austro-Hungarian Empire": {t:["The 1867 Compromise turned the Habsburg lands into a Dual Monarchy: Austria and Hungary under one ruler, Franz Joseph.","Its Vienna produced Freud, Mahler, Klimt and Wittgenstein, while Bohemia became a major industrial region.","The war it began in 1914 broke its multinational army, and it dissolved into successor states in October 1918."],dyk:"Budapest was only created in 1873, by uniting Buda, Óbuda and Pest, and grew to almost 900,000 people by 1910.",ev:[["1866","Prussia defeats Austria at Königgrätz, excluding it from German affairs"],["1867","The Ausgleich creates the Dual Monarchy; Franz Joseph is crowned King of Hungary"],["1878","Austria-Hungary occupies Bosnia-Herzegovina"],["1907","Austria introduces universal male suffrage for the Reichsrat"],["1914","Gavrilo Princip assassinates Archduke Franz Ferdinand in Sarajevo"],["1916","Brusilov Offensive breaks the army; Franz Joseph dies in November"],["1918","The empire dissolves; armistice of Villa Giusti signed on 3 November"]]},
  "Ayyubid Empire": {t:["Founded by the Kurdish commander Saladin, it united Egypt, Syria and Upper Mesopotamia against the Crusader states.","Saladin's victory at Hattin and recapture of Jerusalem in 1187 permanently shifted the balance in the Levant.","Divided among quarrelling kinsmen, it was overthrown by its own mamluk soldiers in 1250 and finished by the Mongols."],dyk:"Saladin's nephew, Sultan al-Kamil, later handed Jerusalem to Emperor Frederick II by treaty in 1229, in return for help against his own Ayyubid relatives.",ev:[["1171","Saladin ends the Fatimid Caliphate, restoring Egypt to Sunni Abbasid allegiance"],["1174","After Nur al-Din's death, Saladin takes Damascus"],["1187","Saladin destroys the Crusader army at Hattin and takes Jerusalem"],["1192","Treaty of Jaffa ends the Third Crusade with Jerusalem still in Ayyubid hands"],["1193","Saladin dies, triggering a succession struggle among his sons"],["1229","Al-Kamil cedes Jerusalem to Holy Roman Emperor Frederick II"],["1250","Bahri mamluks murder Sultan Turanshah and seize Egypt"],["1259–1260","Mongols invade the Levant, sack Aleppo and end Ayyubid rule in Syria"]]},
  "Aztec Empire": {t:["The Triple Alliance of Tenochtitlan, Texcoco and Tlacopan ruled central Mexico from 1428 through a vast tribute system.","Tenochtitlan, fed by lake-bed chinampa gardens, held 200,000 or more people, one of the largest cities in the world.","It fell in under two years to smallpox and to a Spanish-led army made up mostly of its own resentful neighbours."],dyk:"At the final siege of Tenochtitlan, Cortés's army may have numbered up to 100,000 warriors, of whom fewer than 1,000 were Spaniards.",ev:[["c. 1325","The Mexica settle on a swampy island in Lake Texcoco, founding Tenochtitlan"],["1428","Itzcoatl's coalition defeats Azcapotzalco and the Triple Alliance is formed"],["1479","The Purépecha rout Axayacatl's army, fixing the empire's western frontier"],["1487","Ahuitzotl rededicates the enlarged Templo Mayor"],["1502","Moctezuma II comes to power and centralises tribute and appointments"],["1519","Hernán Cortés enters Tenochtitlan as Moctezuma II's guest"],["1520","Spanish flee Tenochtitlan on La Noche Triste; smallpox then ravages the city"],["1521","Tenochtitlan falls after a three-month siege; Cuauhtémoc is captured"]]},
  "Babylonian Empire": {t:["Under Hammurabi, a small Amorite city-state became the master of Mesopotamia in barely a decade of conquest.","His Code of 282 laws is the most complete legal collection to survive from the ancient Near East.","Lacking strong institutions, the empire fragmented soon after his death and ended with a Hittite raid around 1595 BCE."],dyk:"Hammurabi destroyed the city of Eshnunna not by storming it but by damming and then releasing floodwater against it.",ev:[["c. 1894 BCE","Sumu-abum takes control of Babylon and begins building its walls"],["c. 1792 BCE","Hammurabi becomes king of Babylon"],["1764 BCE","Hammurabi defeats an Elamite-led coalition, launching his conquests"],["1763 BCE","Hammurabi conquers Larsa, bringing all southern Mesopotamia under his rule"],["1761 BCE","Hammurabi conquers his former ally Mari"],["c. 1754 BCE","The Code of Hammurabi is inscribed"],["1750 BCE","Hammurabi dies; his son Samsu-iluna soon faces widespread revolt"],["c. 1595 BCE","Hittite king Mursili I sacks Babylon, ending the First Dynasty"]]},
  "Benin Empire": {t:["An Edo kingdom in southern Nigeria whose Obas built a regional empire from Benin City from the 15th century.","Royal guilds produced the Benin Bronzes, among the finest figurative sculpture of sub-Saharan Africa.","A British expedition burned Benin City in 1897 and looted its art, now at the centre of the restitution debate."],dyk:"Much of the metal for the Benin Bronzes came from Portuguese brass manillas, horseshoe-shaped bracelets used as currency in trade.",ev:[["c. 1180","Eweka I founds the Oba dynasty after the Ogiso line loses legitimacy"],["c. 1440","Ewuare the Great seizes the throne, rebuilds Benin City and begins expansion"],["1480s","Portuguese traders under João Afonso de Aveiro reach Benin"],["c. 1515–1516","Oba Esigie defeats a major Igala invasion from the north"],["c. 1606","Death of Ehengbuda, the last of Benin's warrior kings"],["c. 1700–1712","Civil war under Oba Ewuakpe brings the monarchy close to abolition"],["1897","British Punitive Expedition burns Benin City and exiles Oba Ovonramwen"]]},
  "Brazilian Empire": {t:["Prince Pedro declared Brazil independent of Portugal in 1822 and ruled it as Emperor Pedro I.","Under Pedro II the monarchy held a vast country together, while coffee grown by enslaved people drove its wealth.","Abolition in 1888 cost it the planters' support, and an army coup ended the empire in 1889 almost unopposed."],dyk:"Pedro II studied languages including Hebrew, Sanskrit and Tupi, and corresponded with Louis Pasteur and Henry Wadsworth Longfellow.",ev:[["1822","Prince Pedro proclaims independence at the Ipiranga and is acclaimed Emperor Pedro I"],["1831","Pedro I abdicates in favour of his five-year-old son"],["1840","Pedro II is declared of age at fourteen, ending the Regency"],["1850","The Eusébio de Queirós Law effectively ends the transatlantic slave trade"],["1864","Paraguayan War begins; Brazil will bear most of six years of fighting"],["1871","The Law of the Free Womb is passed"],["1888","Princess Isabel signs the Lei Áurea, abolishing slavery"],["1889","Marshal Deodoro da Fonseca's coup ends the monarchy"]]},
  "British Empire": {t:["The largest empire in history, ruling roughly a quarter of the world's people at its peak around 1920.","Naval supremacy, industrial power and the City of London spread its laws, parliaments and language worldwide.","Two world wars drained its wealth; after Indian independence in 1947 it dissolved within a few decades."],dyk:"The Indian Civil Service ran a country of some 300 million people with a cadre of only about 1,000 to 1,200 senior officers.",ev:[["1607","English settlers found Jamestown, Virginia, the first permanent colony in the Americas"],["1707","Acts of Union join England and Scotland as the Kingdom of Great Britain"],["1763","Treaty of Paris ends the Seven Years' War, stripping France of Canada"],["1805","The Royal Navy wins at Trafalgar, securing a century of naval supremacy"],["1857","The Indian Rebellion leads to the abolition of East India Company rule"],["1947","India gains independence, removing the empire's most vital possession"],["1956","The Suez Crisis exposes Britain's inability to act against US wishes"],["1997","Britain hands Hong Kong to China, formally closing the imperial era"]]},
  "Byzantine Empire": {t:["The eastern Roman Empire, ruled from Constantinople, whose people called themselves Romans for over 1,100 years.","It preserved Roman law in Justinian's Code and Greek learning, and spread Orthodox Christianity to Russia and the Balkans.","Manzikert in 1071 and the crusader sack of 1204 crippled it; the Ottomans took Constantinople in 1453."],dyk:"Hagia Sophia, completed under Justinian in 537, remained the largest church in the world for nearly a thousand years.",ev:[["330","Constantine I dedicates Constantinople on the site of Byzantion"],["395","Death of Theodosius I divides the empire permanently into east and west"],["537","Justinian completes the Hagia Sophia"],["717–718","Leo III's Greek fire helps defeat the second Arab siege of Constantinople"],["1071","Seljuk Turks defeat and capture Romanos IV Diogenes at Manzikert"],["1204","The Fourth Crusade sacks Constantinople and founds a Latin Empire"],["1261","Michael VIII Palaiologos recovers Constantinople from the Latins"],["1453","Mehmed II captures Constantinople; Constantine XI dies on the walls"]]},
  "Carolingian Empire": {t:["Charlemagne's Frankish empire united much of Western and Central Europe and revived the Western imperial title in 800.","Its scholars copied much of the classical Latin literature that survives today, in the new Carolingian minuscule script.","The Frankish custom of dividing realms among sons split it at Verdun in 843 and broke it apart for good by 888."],dyk:"Charlemagne's silver penny, struck at 240 to the pound, was the basis of the pound-shilling-penny system used in Britain until 1971.",ev:[["732","Charles Martel checks an Umayyad raid near Tours and Poitiers"],["751","Pepin the Short deposes the last Merovingian king and is made king with papal approval"],["774","Charlemagne conquers the Lombard kingdom and becomes King of the Lombards"],["778","Basques destroy Charlemagne's rearguard under Roland at Roncevaux Pass"],["800","Pope Leo III crowns Charlemagne emperor in Rome on Christmas Day"],["814","Louis the Pious inherits the undivided empire"],["843","Treaty of Verdun divides the empire among Charlemagne's grandsons"],["887","Charles the Fat is deposed and the empire fragments permanently"]]},
  "Chagatai Empire": {t:["The Mongol realm that Genghis Khan allotted to his son Chagatai, spanning Central Asia's steppe and Silk Road cities.","It produced Timur and, through him, a Chagataid line that helped legitimise the Mughal emperors of India.","Torn between nomadic tribes and settled Muslim cities, it split apart, losing Transoxiana to Timur by 1370."],dyk:"The city of Qarshi in Uzbekistan takes its name from the palace that Kebek Khan built there, near Nasaf, in the early 14th century.",ev:[["1227","Chagatai Khan begins his rule over the appanage allotted by Genghis Khan"],["1260","Alghu exploits the Mongol civil war to assert real independence"],["1299","Qutlugh Khwaja leads a great Chagataid army to the outskirts of Delhi"],["c. 1321","Kebek Khan introduces a standardised silver coinage, the kebeks"],["1334","Eastern nomadic tribes revolt against Tarmashirin and overthrow him"],["1360–1361","Tughlugh Timur briefly reunites the khanate"],["1370","Timur completes his seizure of power in Transoxiana"],["1514","The Yarkent Khanate is founded as a Chagataid successor state"]]},
  "Chaldean Empire": {t:["The Neo-Babylonian Empire rose on Assyria's ruins and, under Nebuchadnezzar II, dominated the Near East.","Its destruction of Jerusalem and the Babylonian captivity reshaped Judaism into a portable, text-centred faith.","Weak successors and a king who neglected Marduk let Cyrus the Great take Babylon almost unopposed in 539 BCE."],dyk:"Babylonian sky-watching was so renowned that 'Chaldean' became a byword for astronomer and astrologer in the Greek and Roman worlds.",ev:[["626 BCE","Nabopolassar seizes Babylon and restores native Babylonian kingship"],["612 BCE","Babylonians and Medes sack Nineveh, the Assyrian capital"],["605 BCE","Crown prince Nebuchadnezzar II defeats Necho II's Egyptians at Carchemish"],["597 BCE","Nebuchadnezzar captures Jerusalem and deports King Jehoiachin"],["587/586 BCE","Babylonians destroy Jerusalem and its Temple after a second siege"],["c. 585 BCE","Babylonians begin a thirteen-year siege of the island city of Tyre"],["562 BCE","Nebuchadnezzar II dies; four kings follow in six years"],["539 BCE","Cyrus the Great wins at Opis and Babylon falls without real resistance"]]},
  "Darfur Sultanate": {t:["The Keira sultans ruled Darfur from Jebel Marra for over 250 years, building an Islamic state in the eastern Sahel.","Its Forty Days Road carried slaves, ivory and feathers to Egypt, and West African pilgrims passed through it to Mecca.","Conquered in 1874 and revived in 1898, it fell to an Anglo-Egyptian force with aircraft in 1916."],dyk:"Much of what we know of the sultanate's court comes from Muhammad al-Tunisi, a Tunisian traveller who lived in Darfur from about 1803 to 1811.",ev:[["c. 1650","Suleiman Solong unites the Fur under the Keira dynasty"],["c. 1682","Ahmad Bukr begins his reign and makes Islam the religion of the state"],["c. 1791","Sultan Abd al-Rahman fixes the royal court at El Fasher"],["1821","Egypt conquers Kordofan, cutting Darfur's eastern trade"],["1874","Al-Zubayr defeats Sultan Ibrahim at Manawashi and Darfur is annexed by Egypt"],["1898","Ali Dinar returns to El Fasher and restores the sultanate"],["1916","Anglo-Egyptian force wins at Birinjiya; Ali Dinar is killed in November"]]},
  "Delhi Sultanate": {t:["Five dynasties of Turkic and Afghan origin ruled northern India from Delhi for 320 years, from 1206 to 1526.","It repelled repeated Mongol invasions and fostered the Indo-Islamic culture of the Qutb Minar and Amir Khusrau.","Overreach, provincial breakaways and Timur's sack of Delhi weakened it before Babur won at Panipat in 1526."],dyk:"The Moroccan traveller Ibn Battuta served as a qazi, or judge, at the court of Muhammad bin Tughlaq in Delhi from 1334.",ev:[["1206","Qutb ud-Din Aibak founds the Mamluk or Slave Dynasty after Muhammad of Ghor's murder"],["1229","Abbasid caliph sends Iltutmish a diploma recognising him as sultan"],["1299","Alauddin Khalji's forces turn back a Mongol army that reaches Delhi's outskirts"],["1311","Malik Kafur plunders the Pandya lands around Madurai"],["1327","Muhammad bin Tughlaq forcibly moves the capital to Daulatabad"],["1347","The Bahmani Sultanate breaks away in the Deccan"],["1398","Timur sacks Delhi and carries off its artisans to Samarkand"],["1526","Babur defeats Ibrahim Lodi at the First Battle of Panipat"]]},
  "Dutch Empire": {t:["A small republic built a trading empire across four continents through the VOC and the West India Company.","The VOC's permanent capital and tradable shares created a model of the joint-stock company still recognisable today.","Weakened by wars with Britain, the VOC was dissolved in 1799; Indonesian independence in 1949 ended its Asian empire."],dyk:"Hugo Grotius wrote Mare Liberum (1609) in defence of the VOC, and it became a founding text of international law.",ev:[["1602","The States-General merges rival traders into the VOC with quasi-sovereign powers"],["1619","Jan Pieterszoon Coen founds Batavia on Java"],["1641","The VOC captures Malacca from Portugal"],["1652","Jan van Riebeeck founds the Cape Colony as a VOC resupply station"],["1664","England takes New Netherland and New Amsterdam"],["1799","The VOC is formally dissolved and its debts pass to the Dutch state"],["1942","Japan conquers the Netherlands East Indies in about three months"],["1975","Suriname's independence ends the Dutch colonial empire"]]},
  "Egyptian Empire New Kingdom": {t:["Egypt's imperial age, founded when Ahmose I expelled the Hyksos c. 1550 BCE, stretched from Nubia to the Euphrates.","Nubian gold, Levantine tribute and the Amarna letters' great-power diplomacy made Egypt the hub of the Late Bronze Age world.","It ended not by conquest but by dissolution, as the Bronze Age Collapse and the rising Amun priesthood hollowed out royal power."],dyk:"Ramesses II and the Hittites made peace in 1258 BCE in the earliest treaty to survive in both parties' versions, settling a stalemate after the Battle of Kadesh.",ev:[["c. 1550 BCE","Ahmose I completes the expulsion of the Hyksos and reunites Egypt"],["1457 BCE","Thutmose III defeats a Canaanite coalition at Megiddo after a daring march through the Aruna pass"],["c. 1353 BCE","Akhenaten begins his reign, elevating the Aten and moving the capital to Akhetaten"],["1274 BCE","Ramesses II fights the Hittite king Muwatalli II to a draw at the Battle of Kadesh"],["1258 BCE","Egypt and the Hittites conclude a peace treaty acknowledging strategic stalemate"],["c. 1177 BCE","Ramesses III repels land and sea invasions by the Sea Peoples"],["c. 1153 BCE","Ramesses III is assassinated by harem conspirators"],["c. 1070 BCE","Death of Ramesses XI ends the New Kingdom amid administrative dissolution"]]},
  "Elamite Confederation": {t:["Elam joined lowland Susa and highland Anshan in southwestern Iran, a pairing that let it survive conquest and revive for two millennia.","It repeatedly broke Mesopotamian powers, sacking Ur and toppling Kassite Babylon, and its rulers once outranked Hammurabi.","Ashurbanipal destroyed Susa c. 646 BCE, but Elamite language and bureaucracy lived on inside the Persian Achaemenid state."],dyk:"The Code of Hammurabi was found at Susa, not Babylon: Elamite kings carried it off as a war trophy c. 1158 BCE, and French excavators recovered it around 1900.",ev:[["c. 2100 BCE","Kutik-Inshushinak of Awan first unifies Susa and the highlands after the Akkadian collapse"],["c. 2004 BCE","Shimashki king Kindattu sacks Ur and captures Ibbi-Sin, last ruler of the Third Dynasty of Ur"],["c. 1765 BCE","Sukkalmah Siwe-Palar-Khuppak conquers Eshnunna and is addressed as 'father' by Hammurabi"],["c. 1158 BCE","Shutruk-Nahhunte and Kutir-Nahhunte overthrow the Kassite dynasty of Babylon"],["720 BCE","Humban-nikash I fights Sargon II of Assyria at the Battle of Der"],["694 BCE","Sennacherib's son Ashur-nadin-shumi is handed to Elam and dies in captivity"],["c. 646 BCE","Ashurbanipal destroys Susa, looting its treasuries and desecrating royal tombs"],["540s BCE","Cyrus the Great begins absorbing Elam into the Achaemenid Empire"]]},
  "Empire of Japan": {t:["Born of the 1868 Meiji Restoration, Japan went from feudal isolation to industrial great power in barely a generation.","Its 1905 defeat of Russia showed the colonised world that European supremacy was not inevitable.","A system with no check on its military drove it into a war it could not sustain, ending in surrender in 1945."],dyk:"Japan imported roughly 80 per cent of its oil from the United States, so the American oil embargo of August 1941 pushed Tokyo towards attacking Pearl Harbor.",ev:[["1868","Meiji Restoration overthrows the Tokugawa shogunate after some 265 years"],["1889","Meiji Constitution establishes a constitutional monarchy with an Imperial Diet"],["1894","First Sino-Japanese War begins, ending in Japanese victory over Qing China in 1895"],["1905","Admiral Togo annihilates the Russian fleet at Tsushima, sealing victory over Russia"],["1931","Army officers stage the Mukden Incident, launching independent action in Manchuria"],["1941","US oil embargo in August pushes Japan towards the attack on Pearl Harbor"],["1942","Japan loses four fleet carriers at Midway, surrendering the strategic initiative"],["1945","After Hiroshima, Nagasaki and Soviet entry into the war, Japan surrenders aboard USS Missouri"]]},
  "Ethiopian Empire": {t:["A Christian highland kingdom ruled by the Solomonic dynasty, which claimed descent from Solomon and the Queen of Sheba, from 1270 to 1974.","Menelik II's victory over Italy at Adwa in 1896 kept Ethiopia independent and made it a symbol for pan-Africanists worldwide.","An unreformed feudal land system and the concealed Wollo famine brought down Haile Selassie and the monarchy in 1974."],dyk:"Ethiopia's survival in 1543 owed much to some 400 Portuguese musketeers, whose firepower helped Emperor Galawdewos defeat and kill Ahmad Gran at Wayna Daga.",ev:[["1270","Yekuno Amlak overthrows the last Zagwe king and founds the Solomonic dynasty"],["1445","Zara Yaqob defeats the Adal Sultanate at the Battle of Gomit"],["1529","Ahmad Gran crushes Lebna Dengel at the Battle of Shimbra Kure"],["1543","Galawdewos, aided by Portuguese musketeers, defeats and kills Ahmad Gran at Wayna Daga"],["1769","The Zemene Mesafint, the Era of the Princes, begins as regional lords eclipse the emperors"],["1896","Menelik II routs the Italian army at Adwa, securing Ethiopian independence"],["1936","Italian forces using aerial bombardment and poison gas capture Addis Ababa"],["1974","The Derg deposes Haile Selassie; the monarchy is abolished in March 1975"]]},
  "Fatimid Caliphate": {t:["An Ismaili Shia caliphate born of a secret missionary network in North Africa, set up in 910 as a rival to Abbasid Baghdad.","From Cairo, which it founded, it controlled Red Sea to Mediterranean trade and built al-Azhar, still a leading centre of Islamic learning.","Famine, army factions and a schism in 1094 eroded it until Saladin quietly restored Abbasid prayers in 1171."],dyk:"The Nizari Ismailis who broke away after the 1094 succession crisis gave rise to the imams known today as the Aga Khans, a lineage tracing back to the Fatimid missionary network.",ev:[["910","Abdallah al-Mahdi Billah is proclaimed caliph at Raqqada after the Kutama overthrow the Aghlabids"],["969","General Jawhar al-Siqilli conquers Egypt; Cairo is founded north of Fustat"],["970","The al-Azhar mosque is begun, later developing into a great teaching institution"],["c. 1048","The Zirid governor of Ifriqiya renounces Fatimid allegiance, severing North Africa"],["1073","Badr al-Jamali arrives and takes over as vizier and commander after years of chaos"],["1094","Succession crisis over Nizar splits the Ismaili community permanently"],["1099","The First Crusade captures Jerusalem"],["1171","Saladin restores prayers for the Abbasid caliph; the last Fatimid caliph al-Adid dies"]]},
  "French Empire": {t:["France built two colonial empires: one in North America and the Caribbean, lost in 1763, and a larger one in Africa and Asia.","Plantation slavery made Saint-Domingue the world's richest colony, while the later empire extracted raw materials for French industry.","Nationalist wars from Dien Bien Phu to Algeria ended it, leaving French as an official language in twenty-nine countries."],dyk:"By the 1780s Saint-Domingue, now Haiti, produced around 40 per cent of Europe's sugar and some 60 per cent of its coffee.",ev:[["1534","Jacques Cartier reaches the Gulf of St. Lawrence and claims land for Francis I"],["1608","Samuel de Champlain founds Quebec as the capital of New France"],["1664","Colbert establishes the French East India Company"],["1763","Treaty of Paris cedes Canada and lands east of the Mississippi to Britain"],["1830","France invades Algiers, beginning the second colonial empire"],["1954","The Viet Minh force the surrender of the French garrison at Dien Bien Phu"],["1960","Fourteen sub-Saharan colonies and trust territories become independent"],["1962","The Evian Accords bring Algerian independence after eight years of war"]]},
  "Garamantian Empire": {t:["A Saharan kingdom in Libya's Fezzan, sustained by underground foggara channels tapping fossil water beneath the desert.","It controlled trans-Saharan routes, sending ivory, enslaved people and wild animals to Carthaginian and Roman markets.","As the water table sank below the channels and trade faltered, it faded into scattered oases before the Arab conquest."],dyk:"In the Wadi al-Ajal alone the Garamantes dug an estimated 550 or more foggara channels with over 100,000 vertical shafts to bring water to their fields.",ev:[["20-19 BCE","Lucius Cornelius Balbus captures Garama, earning Rome's last triumph for a non-imperial general"],["69","The Garamantes join Oea against Leptis Magna and are driven back by Valerius Festus"],["c. 202","Septimius Severus campaigns against the Garamantes and sets outposts at Ghadames and Bu Njem"],["429","The Vandal conquest of North Africa begins, disrupting Mediterranean trade demand"],["c. 500","Garama is greatly reduced as falling groundwater starves the foggara system"],["640s","Arab expeditions into the Fezzan begin, meeting little significant resistance"]]},
  "German Empire": {t:["Proclaimed at Versailles in 1871 after victory over France, it united German states under Prussian leadership.","It became continental Europe's industrial giant and created the world's first national social insurance system.","After Bismarck's dismissal its diplomacy unravelled; defeat in the First World War ended it in revolution in 1918."],dyk:"By 1913 German chemical firms such as BASF, Bayer and Hoechst supplied roughly 80 to 90 per cent of the world's synthetic dyes.",ev:[["1871","Wilhelm I is proclaimed German Emperor in the Hall of Mirrors at Versailles"],["1878","Bismarck's Anti-Socialist Laws target the rising labour movement"],["1883","Bismarck introduces national health insurance, the first of his social insurance laws"],["1890","Wilhelm II dismisses Bismarck; the Reinsurance Treaty with Russia lapses"],["1898","The first Naval Law launches Tirpitz's challenge to British sea power"],["1914","The Schlieffen Plan fails at the Marne, locking Germany into a two-front war"],["1916","Verdun and the Somme cost roughly 300,000 German dead without a breakthrough"],["1918","The Kiel mutiny sparks revolution; Wilhelm II abdicates and the armistice follows"]]},
  "Ghana Empire": {t:["Wagadou, the Soninke kingdom Arab writers called Ghana, sat between West Africa's goldfields and the Saharan caravan routes.","It grew rich by taxing gold going north and salt going south, and its gold supplied mints across North Africa and Muslim Spain.","Almoravid attacks, shifting trade routes and drought broke its power; Mali absorbed what remained in the thirteenth century."],dyk:"Ghana's king kept every gold nugget found in the kingdom for himself, letting subjects trade only gold dust, a deliberate way to stop the price of gold from collapsing.",ev:[["c. 750","Wagadou crystallises as a recognisable state under Soninke rule"],["c. 992","Ghana captures Awdaghast, the southern terminus of the western trans-Saharan route"],["1054","The Almoravids seize Awdaghast, ending some sixty years of Ghanaian control"],["1068","Al-Bakri completes his famous description of the gilded royal court"],["1076","Almoravids sack Koumbi Saleh, reducing Ghana for a time to a tributary"],["1087","Death of the Almoravid leader Abu Bakr ibn Umar lets the Soninke regain independence"],["c. 1235","Sundiata Keita defeats Sumanguru at Kirina; Ghana's remnant passes into the Mali Empire"],["c. 1240","The old capital is traditionally said to have been abandoned"]]},
  "Gokturk Empire": {t:["The first state to bear the name Turk, a steppe khaganate that at its peak stretched from Manchuria towards the Black Sea.","It protected Silk Road trade, drew vast silk tribute from China and left the Orkhon Inscriptions, the oldest major Turkic texts.","Rival claimants under lateral succession and Chinese divide-and-rule broke it twice; the Uyghurs ended it for good in 744."],dyk:"According to the Orkhon Inscriptions, Ilterish Qaghan began rebuilding the fallen Turkic empire in 682 with just seventeen men in the Yin Shan mountains.",ev:[["552","Bumin destroys the Rouran and declares himself Qaghan of the Turks"],["568","The Gokturks send their first embassy to Constantinople, led by the Sogdian Maniakh"],["576","Gokturk forces reach the Crimea and besiege the Byzantine city of Bosporus"],["c. 603","The First Khaganate splits into eastern and western halves"],["630","Tang China conquers the Eastern Khaganate and captures Illig Qaghan"],["682","Ilterish Qaghan founds the Second Khaganate through guerrilla warfare"],["734","Bilge Qaghan is poisoned by one of his own ministers"],["744","Uyghurs, Karluks and Basmyls seize Otuken and kill the last Gokturk qaghan"]]},
  "Gupta Empire": {t:["A north Indian empire built from the Ganges plain by Chandragupta I and Samudragupta from around 320 CE.","Its age saw Aryabhata's mathematics, Kalidasa's poetry and art that shaped Southeast Asia, earning it the name Golden Age of India.","Huna invasions and feudatories who broke away dissolved it into regional kingdoms by the mid-sixth century."],dyk:"Aryabhata, whose Aryabhatiya dates to 499 CE, approximated pi to four decimal places and proposed that the earth rotates on its axis.",ev:[["c. 320","Chandragupta I ascends and takes the title Maharajadhiraja, great king of kings"],["c. 335","Samudragupta begins the campaigns recorded on the Allahabad Pillar"],["c. 375","Chandragupta II succeeds and later defeats the Shaka satraps of western India"],["c. 455","Skandagupta takes the throne and repels a major Huna incursion"],["499","Aryabhata composes the Aryabhatiya"],["c. 500","Hunas under Toramana and Mihirakula occupy much of northwestern and central India"],["c. 528","Aulikara king Yashodharman, not a Gupta, defeats Mihirakula"],["c. 540","Vishnugupta, the last recognised Gupta emperor, rules only a remnant kingdom"]]},
  "Han Dynasty": {t:["Founded by the commoner Liu Bang in 202 BCE, the Han replaced Qin brutality with Confucian government and lasted four centuries.","It opened the Silk Road, drove back the Xiongnu and built a bureaucratic model of rule that China kept until 1912.","Landed elites, court feuds and the Yellow Turban Rebellion handed power to warlords, and the dynasty ended in 220."],dyk:"China's majority ethnic group still calls itself Han, after this dynasty, more than eighteen centuries after it fell.",ev:[["202 BCE","Liu Bang defeats Xiang Yu and proclaims himself emperor as Gaozu"],["141 BCE","Emperor Wu takes the throne, beginning the dynasty's most expansive reign"],["124 BCE","The Imperial Academy is founded to train officials in the Confucian classics"],["119 BCE","Wei Qing and Huo Qubing drive Xiongnu power beyond the Gobi Desert"],["2","The Han census records a population of nearly 60 million"],["25","The dynasty is restored as the Eastern Han after Wang Mang's usurpation"],["184","The Yellow Turban Rebellion erupts amid famine and peasant displacement"],["220","Cao Pi deposes Emperor Xian and declares the Wei dynasty, ending the Han"]]},
  "Hittite Empire": {t:["A Bronze Age power ruled from Hattusa in central Anatolia that rivalled Egypt for control of Syria and the Levant.","Its vassal treaties and its peace with Ramesses II are among the earliest milestones of international law and diplomacy.","It vanished in the Bronze Age Collapse when Hattusa was abandoned and burned c. 1180 BCE; Neo-Hittite city-states carried on its legacy."],dyk:"A replica of the Hittite-Egyptian peace treaty, the earliest to survive in both parties' versions, hangs at the United Nations headquarters in New York.",ev:[["c. 1650 BCE","Hattusili I founds the Old Kingdom with Hattusa as his capital"],["c. 1595 BCE","Mursili I raids Babylon, ending the First Babylonian Dynasty"],["c. 1525 BCE","The Edict of Telipinu recounts decades of palace murders and coups"],["c. 1344 BCE","Suppiluliuma I takes the throne and goes on to dismantle the Mitanni kingdom"],["1274 BCE","Muwatalli II fights Ramesses II at Kadesh, perhaps the largest chariot battle of antiquity"],["c. 1259 BCE","Hattusili III and Ramesses II conclude the Treaty of Kadesh"],["c. 1180 BCE","Hattusa is abandoned and burned under Suppiluliuma II"]]},
  "Holy Roman Empire": {t:["A loose union of princes, bishops and free cities in central Europe, under an elected emperor from 962 to 1806.","Its fragmentation let the Reformation survive and produced religious settlements that shaped the modern idea of state sovereignty.","Napoleon's Confederation of the Rhine made the title meaningless, and Francis II quietly dissolved the empire in 1806."],dyk:"The empire had no standing army for most of its history; its military strength depended on contingents the princes sent only when politically willing.",ev:[["800","Pope Leo III crowns Charlemagne emperor in Rome on Christmas Day"],["962","Otto I is crowned emperor by Pope John XII, the empire's functional founding"],["1176","The Lombard League defeats Frederick Barbarossa at Legnano"],["1356","Charles IV's Golden Bull fixes the election of the emperor by seven electors"],["1517","Martin Luther launches the Reformation at Wittenberg"],["1555","The Peace of Augsburg lets rulers choose Catholicism or Lutheranism for their lands"],["1648","The Peace of Westphalia ends the Thirty Years' War and lets princes make foreign alliances"],["1806","Francis II abdicates and declares the Holy Roman Empire dissolved"]]},
  "Ilkhanate": {t:["The Mongol khanate founded by Hulagu in Persia and Iraq after he destroyed the Abbasid Caliphate at Baghdad in 1258.","Under Ghazan it became a Persianised Islamic state whose reforms, trade and court scholarship linked China and the Mediterranean.","When Abu Said died without an heir in 1335 it broke into rival successor states such as the Jalayirids and Chupanids."],dyk:"Rashid al-Din's Jami al-Tawarikh, written at the Ilkhanid court with Mongol, Chinese, Persian and European informants, is often called the first universal history of Eurasia.",ev:[["1256","Hulagu destroys the Nizari Ismaili state and takes Alamut"],["1258","Mongol forces capture Baghdad and execute the Abbasid caliph al-Mustasim"],["1260","The Mamluks defeat Kitbuqa's Mongol army at Ain Jalut in Galilee"],["1287","The monk Rabban Sauma begins an embassy to Europe seeking an alliance against the Mamluks"],["1295","Ghazan converts to Islam and begins sweeping reforms with Rashid al-Din"],["1299","Ghazan wins at Wadi al-Khaznadar, briefly taking Damascus"],["1318","Rashid al-Din, the state's ablest administrator, is executed"],["1335","Abu Said dies without an heir and the Ilkhanate fragments"]]},
  "Italian Empire": {t:["Newly unified Italy's late bid for colonies, spanning Eritrea, Somaliland, Libya, the Dodecanese and, briefly, Ethiopia.","Under Mussolini it became a vehicle for Fascist dreams of a new Roman empire, enforced with poison gas, camps and racial laws.","It collapsed within three years in the Second World War, and the 1947 Treaty of Paris formally stripped Italy of its colonies."],dyk:"In 1938 Governor Italo Balbo oversaw the arrival in Libya of some twenty thousand Italian settlers in a single state-organised convoy.",ev:[["1882","The Italian government takes over Assab Bay on the Red Sea, its first colonial foothold"],["1890","The colony of Eritrea is formally proclaimed"],["1896","Menelik II routs General Baratieri's army at Adwa"],["1911","The Italo-Turkish War begins, bringing coastal Libya and the Dodecanese under Italian control"],["1931","Libyan resistance leader Omar Mukhtar is executed"],["1936","Mussolini proclaims the empire after Addis Ababa falls; Africa Orientale Italiana is formed"],["1941","British and Commonwealth forces end Italian rule in East Africa; Haile Selassie returns"],["1943","The Allies invade Sicily; Mussolini is dismissed and Italy signs an armistice"]]},
  "Jolof Empire": {t:["A Wolof-led confederation in Senegambia, uniting Waalo, Cayor, Baol, Sine and Saloum under an overlord called the buurba.","It linked the interior with the Atlantic coast just as Portuguese traders arrived, and spread Wolof language across the region.","Atlantic wealth let coastal vassals break away; Cayor's victory at Danki c. 1549 ended Jolof's imperial phase."],dyk:"In 1488 the exiled Jolof prince Bemoim was received and baptised at the court of King Joao II in Lisbon.",ev:[["c. 1350","Ndiadiane Ndiaye, by tradition, draws the Wolof and Serer states into the Jolof confederation"],["1455","Venetian Alvise Cadamosto sees Portuguese traders exchanging horses for slaves on the Senegal coast"],["1488","Exiled Jolof prince Bemoim is baptised at the court of Joao II in Lisbon"],["c. 1549","Amari Ngone Sobel Fall of Cayor defeats and kills the buurba Leele Fuli Fak at Danki"],["1890","The rump kingdom of Jolof is absorbed into French Senegal"]]},
  "Kaabu Empire": {t:["A Mandinka state in today's Guinea-Bissau and Senegambia that began as a western province of the Mali Empire.","Ruled by the nyancho warrior aristocracy, it grew rich by selling war captives into the Atlantic slave trade for guns and goods.","Fula forces from Futa Jallon destroyed its capital Kansala in 1867, and the region later fell to European colonial rule."],dyk:"At the fall of Kansala in 1867, the mansaba Janke Waali had the gunpowder stores ignited, destroying the city, its defenders and many of the attackers.",ev:[["13th century","Tiramakhan Traore, by tradition, founds Kaabu as a western province of Mali"],["15th-16th centuries","Kaabu becomes autonomous as Mali's central authority weakens"],["1588","The Portuguese found Cacheu, a key coastal port for Kaabu's slave trade"],["1867","Futa Jallon forces besiege and destroy Kansala, ending the empire"]]},
  "Kanem-Bornu Empire": {t:["A Lake Chad empire ruled for close to eight centuries by the Sayfawa dynasty, one of the longest in world history.","Its control of the trans-Saharan route to Tripoli and its Islamic institutions tied the central Sudan to the Muslim world.","The Fulani jihad, the rise of the shehus and Rabih's 1893 conquest ended it before European powers divided the land."],dyk:"As early as the thirteenth century, a hostel for students and pilgrims from Kanem was maintained in Cairo.",ev:[["c. 1085","Mai Hummay, by tradition, adopts Islam for the ruling house"],["c. 1221","Mai Dunama Dabbalemi begins a reign that expands and institutionalises the state"],["c. 1470","Driven from Kanem by the Bulala, Mai Ali Gaji founds a new capital at Ngazargamu in Bornu"],["1808","Fulani jihadist forces sack Ngazargamu"],["1846","Umar, son of al-Kanemi, ends the Sayfawa line and founds the dynasty of the shehus"],["1893","Sudanese warlord Rabih az-Zubayr conquers Bornu and destroys Kukawa"],["1900","French forces kill Rabih at Kousseri; Britain, France and Germany partition the territory"]]},
  "Khazar Khaganate": {t:["A Turkic steppe state between the Volga and the Caucasus, ruled jointly by a sacral khagan and a military bek.","It held back Arab expansion north of the Caucasus and taxed the Volga trade linking the Islamic world to Northern Europe.","Its ruling elite famously converted to Judaism; Sviatoslav of Kiev's campaign of the 960s brought the khaganate down."],dyk:"The Byzantine emperor Constantine V married the Khazar princess Tzitzak, and their son reigned as Leo IV, known as 'the Khazar'.",ev:[["mid-600s","The khaganate emerges on the Pontic-Caspian steppe as the Western Turkic Khaganate fragments"],["730","The Khazars destroy an Arab army at Marj Ardabil"],["737","Marwan ibn Muhammad's great campaign forces a temporary Khazar submission"],["c. 840","The fortress of Sarkel is built on the Don with Byzantine engineers"],["c. 965","Sviatoslav I of Kiev captures Sarkel and sacks Atil, dismantling the khaganate"]]},
  "Khmer Empire": {t:["A Cambodian empire founded in 802, whose god-kings ruled much of mainland Southeast Asia from Angkor.","Vast reservoirs and canals fed a huge population and paid for Angkor Wat and Angkor Thom, among the world's great monuments.","Strained waterworks, drought, Thai invasions and shifting trade led the court to abandon Angkor for the Phnom Penh region."],dyk:"An inscription at the temple of Ta Prohm records thousands of villages and attendants assigned to its upkeep, showing how temples worked as economic centres.",ev:[["802","Jayavarman II is consecrated universal monarch on Phnom Kulen, founding the empire"],["late 800s","Yasovarman I settles the capital at Angkor"],["1177","Cham forces sack Angkor"],["1203","Jayavarman VII, having expelled the Cham, subjugates Champa itself"],["1296","Chinese envoy Zhou Daguan arrives and later writes a vivid account of Angkor"],["1431","The Thai kingdom of Ayutthaya captures Angkor, by traditional dating"]]},
  "Khwarazmian Empire": {t:["A Turkic-ruled, Persianised empire that rose from the Amu Darya oasis of Khwarazm to rule from western Iran to the Syr Darya.","It grew rich on Silk Road trade, but rapid conquests left it with divided commands and loyalties it never resolved.","Killing a Mongol envoy in 1218 brought Genghis Khan's invasion, which destroyed the empire and opened Iran to the Mongols."],dyk:"In 1217 Muhammad II marched on Baghdad against the Abbasid caliph, but the campaign was abandoned when snow overwhelmed his army in the Zagros mountains.",ev:[["1172","Ala ad-Din Tekish comes to power and throws off Seljuk overlordship"],["1194","Tekish defeats and kills Toghrul III, the last Seljuk sultan of Iraq"],["1200","Ala ad-Din Muhammad II takes the throne and expands against the Ghurids and Qara Khitai"],["1217","Muhammad II's march on Baghdad is abandoned in the snows of the Zagros"],["1218","Otrar's governor massacres a Mongol-sponsored caravan; the shah executes a Mongol envoy"],["1220","Bukhara and Samarkand fall to Genghis Khan's armies"],["1221","The empire effectively ceases to exist; Jalal ad-Din is defeated on the Indus"],["1231","Jalal ad-Din dies after a decade of resistance in Iran and the Caucasus"]]},
  "Kongo Empire": {t:["A Central African kingdom south of the lower Congo River, ruled from Mbanza Kongo by an elected manikongo.","It was among the first African states to sustain diplomacy with Europe, adopting Christianity and Portuguese literacy.","The Atlantic slave trade fuelled rivalries, and defeat at Mbwila in 1665 tipped it into civil war and long decline."],dyk:"Kongo used nzimbu shells, gathered on the royal fishery of Luanda Island, as currency alongside squares of finely woven raffia cloth.",ev:[["1483","Portuguese navigator Diogo Cao reaches the mouth of the Congo"],["1491","King Nzinga a Nkuwu is baptised as Joao I"],["1509","Afonso I wins the throne by defeating his half-brother Mpanzu a Kitima"],["1526","Afonso I writes to Joao III of Portugal protesting the abuses of the slave trade"],["1568","Jaga invaders drive Alvaro I from his capital until Portuguese troops restore him"],["1665","Portuguese forces defeat Kongo at Mbwila, killing King Antonio I"],["1706","Beatriz Kimpa Vita, leader of the Antonian movement, is executed"],["1709","Pedro IV reoccupies Sao Salvador and nominally reunifies the kingdom"]]},
  "Kushite Empire": {t:["A Nubian kingdom on the Nile south of Egypt, centred first at Napata and later at Meroe.","Its kings conquered Egypt and ruled it as the Twenty-Fifth Dynasty, then built an iron-working, pyramid-building civilisation at Meroe.","Shifting trade, environmental strain and pressure from Aksum ended Kush as a unified state by the mid-fourth century CE."],dyk:"The Kushites built more pyramids, at El-Kurru, Nuri and Meroe, than were built in Egypt itself.",ev:[["c. 728 BCE","Piye defeats the Delta coalition of Tefnakht and records his triumph at Jebel Barkal"],["671 BCE","The Assyrian king Esarhaddon takes Memphis"],["663 BCE","Ashurbanipal's army sacks Thebes, ending Kushite rule in Egypt"],["c. 593 BCE","An Egyptian army under Psamtik II raids Nubia"],["c. 300 BCE","The royal centre's move south to Meroe is complete"],["20s BCE","Kush raids Roman Egypt; Petronius' punitive expedition ends in a peace favourable to Kush"],["c. 350","King Ezana of Aksum records an invasion of Kush along the Nile"]]},
  "Luba Empire": {t:["The Luba Empire was a sacred kingship centred on the Upemba Depression in what is now south-eastern DR Congo.","Its model of royal power, checked by the Bambudye society, was copied by neighbours such as the Lunda across the southern savanna.","A succession war after c. 1870, slave raiding and Congo Free State conquest in the 1890s ended its independence."],dyk:"Luba historians kept royal memory on the lukasa, a hand-held beaded board whose patterns of beads and shells helped Bambudye adepts recall kings, places and lineages.",ev:[["c. 1585","Kalala Ilunga overthrows Nkongolo Mwamba and founds the Second Luba Dynasty"],["c. 1780","Ilunga Sungu begins the reign that opens the empire's apogee"],["c. 1810","Kumwimbe Ngombe succeeds; Luba expeditions push towards Lake Tanganyika"],["c. 1870","Death of Ilunga Kabale triggers a long civil war between rival royal claimants"],["1890s","Congo Free State forces absorb the divided Luba lands into Leopold II's colony"],["1917","Kasongo Nyembo is captured after years of resisting Free State and Belgian rule"]]},
  "Lunda Empire": {t:["The Lunda Empire was a tributary state of the Central African savanna, ruled by a sacred king titled the Mwaant Yaav.","Positional succession and perpetual kinship let it absorb chiefdoms without removing their rulers, linking the interior to Atlantic trade.","Succession disputes, the rise of the Chokwe and colonial partition in the 1890s broke it up, though the Mwaant Yaav title survives."],dyk:"Under perpetual kinship, a new Lunda office-holder inherited his predecessor's identity and relationships, so ties between chiefdoms could last for generations unchanged.",ev:[["16th century","Tradition: Luba hunter-prince Chibinda Ilunga marries the Lunda heiress Lueji, bringing sacred kingship"],["Late 17th century","Mwaant Yaav I, traditionally Naweej I, rules a regional power from the royal musumba"],["c. 1740","An eastern expedition founds the kingdom of Kazembe on the Luapula River"],["Mid-1880s","The Chokwe, armed through the rubber, wax and ivory trades, overrun the Lunda capital"],["1890s","Lunda lands are partitioned between the Congo Free State, Portuguese Angola and Northern Rhodesia"]]},
  "Macedonian Empire": {t:["Philip II turned Macedon from a raided frontier kingdom into the master of Greece with a pike phalanx and Companion cavalry.","Alexander the Great conquered the Achaemenid Empire from Egypt to the Indus, spreading Greek language and cities across Asia.","It split among his generals after 323 BCE, but their kingdoms created the Hellenistic world that Rome later absorbed."],dyk:"Philip II's phalanx carried the sarissa, a pike of up to about six metres, letting several ranks present their points to the enemy at once.",ev:[["359 BCE","Philip II becomes king of Macedon and begins reforming its army"],["338 BCE","Philip defeats Athens and Thebes at Chaeronea and becomes master of Greece"],["334 BCE","Alexander crosses into Asia and wins his first victory at the Granicus"],["331 BCE","Alexander defeats Darius III at Gaugamela, sealing the fall of Persia"],["326 BCE","Alexander defeats Porus at the Hydaspes in India"],["323 BCE","Alexander dies at Babylon, leaving no clear successor"],["168 BCE","Rome defeats the last Antigonid king, Perseus, at Pydna"],["146 BCE","Macedonia becomes a Roman province, ending independent Macedonian rule"]]},
  "Majapahit Empire": {t:["Majapahit was a Hindu-Buddhist kingdom in eastern Java that dominated the archipelago's sea lanes in the 14th century.","Rice from the Brantas valley and control of the spice trade funded fleets, temples and a network of tribute-paying vassals.","Civil war, Malacca's rise and Muslim coastal sultanates such as Demak eroded it; its court culture lived on in Bali."],dyk:"Majapahit's founder Raden Wijaya used a Mongol army sent by Kublai Khan to defeat his rival, then turned on the invaders and drove them from Java.",ev:[["1292","Jayakatwang of Kediri kills Kertanegara, ending the Singhasari kingdom"],["1293","Raden Wijaya expels the Mongols and becomes Majapahit's first king"],["1343","Forces directed by Gajah Mada subjugate Bali"],["1350","Hayam Wuruk begins the reign that marks Majapahit's height"],["1357","The Sundanese royal party is massacred at the Battle of Bubat"],["1365","Mpu Prapanca completes the Nagarakretagama, describing the realm at its peak"],["1404–1406","The Regreg War between the western and eastern courts drains the kingdom"],["c. 1527","Demak conquers the last reduced Majapahit court, probably at Kediri"]]},
  "Mali Empire": {t:["The Mali Empire was a Mandinka state founded by Sundiata Keita that dominated West Africa from the 13th century.","Its gold from Bambuk and Bure fed trans-Saharan trade and made Timbuktu and Djenné centres of commerce and Islamic learning.","Succession disputes, Tuareg and Songhai attacks and shifting trade routes shrank it to its Manding heartland by the 1600s."],dyk:"Mansa Musa spent so much gold in Cairo on his 1324 pilgrimage that it was remembered for years, and Mali soon appeared on the Catalan Atlas of 1375.",ev:[["c. 1235","Sundiata Keita defeats Sumanguru Kanté of Sosso at the Battle of Kirina"],["1240","Mali traditionally captures Koumbi Saleh, the former capital of Ghana"],["c. 1312","Mansa Musa begins his reign, Mali's era of greatest renown"],["1324","Mansa Musa makes his pilgrimage to Mecca, dazzling Cairo with gold"],["1352–1353","Ibn Battuta visits and describes the court of Mansa Sulayman"],["c. 1433","The Tuareg seize Timbuktu and Walata"],["1468","Songhai ruler Sonni Ali captures Timbuktu"],["c. 1610","Death of Mahmud IV, the last powerful mansa; the kingdom splits among his heirs"]]},
  "Mamluk Sultanate": {t:["The Mamluk Sultanate was ruled from Cairo by slave soldiers, renewed by fresh purchases rather than hereditary succession.","It halted the Mongols at Ain Jalut, ended the Crusader states and grew rich on the spice trade between India and Europe.","Plague, Portuguese competition at sea and Ottoman guns brought it down, ending with Selim I's conquest of Egypt in 1517."],dyk:"Though rulers of slave origin, the Mamluk sultans hosted a line of Abbasid caliphs in Cairo from 1261, whose nominal blessing lent them religious legitimacy.",ev:[["1250","Mamluks assassinate Turanshah, the last Ayyubid sultan of Egypt, and seize power"],["1260","Qutuz and Baybars defeat the Mongols at Ain Jalut; Baybars then takes the throne"],["1291","Al-Ashraf Khalil captures Acre, ending the Crusader states"],["1315","Al-Nasir Muhammad orders the rawk, a new land survey that reshapes the iqta system"],["1347","The Black Death reaches Egypt, beginning repeated catastrophic population losses"],["1382","Barquq inaugurates the Burji regime of Circassian mamluks"],["1509","The Portuguese defeat a Mamluk fleet at Diu, cutting customs revenue"],["1517","Selim I wins at Ridaniya and conquers Egypt, ending Mamluk sovereignty"]]},
  "Maratha Empire": {t:["The Maratha Empire grew from Shivaji's hill forts in the Western Ghats into a confederacy that dominated 18th-century India.","It broke Mughal supremacy, reaching Attock on the Indus in 1758 and later controlling Delhi and the Mughal emperor.","Defeat at Panipat in 1761, rivalry among its chiefs and three wars with the East India Company ended its independence in 1818."],dyk:"The Marathas built a capable navy with sea forts such as Sindhudurg; under Kanhoji Angre in the early 18th century it challenged even the English and Dutch.",ev:[["1646","Shivaji captures the fort of Torna, beginning his rise"],["1659","Shivaji kills the Bijapur general Afzal Khan at Pratapgad"],["1674","Shivaji is crowned Chhatrapati at Raigad, formally asserting sovereignty"],["1689","Shivaji's son Sambhaji is executed during the long war with Aurangzeb"],["1728","Peshwa Baji Rao I defeats the Nizam at Palkhed"],["1758","Maratha armies reach Attock on the Indus"],["1761","The Durrani army of Ahmad Shah Abdali crushes the Marathas at the Third Battle of Panipat"],["1818","Peshwa Baji Rao II surrenders to the British and the Peshwa's office is abolished"]]},
  "Maurya Empire": {t:["The Maurya Empire, ruled from Pataliputra, was the first state to unite almost the whole Indian subcontinent.","Its centralised administration and Ashoka's edicts promoting dhamma helped carry Buddhism across Asia.","It fell apart after Ashoka's death and ended c. 185 BCE when Pushyamitra Shunga killed the last emperor, Brihadratha."],dyk:"Ashoka's Lion Capital from Sarnath, carved from polished sandstone over 2,000 years ago, is today the national emblem of the Republic of India.",ev:[["c. 321 BCE","Chandragupta Maurya overthrows the Nanda dynasty of Magadha"],["c. 305–303 BCE","Chandragupta gains the north-west from Seleucus I in exchange for 500 war elephants"],["c. 261 BCE","Ashoka conquers Kalinga, then renounces conquest by force"],["c. 232 BCE","Ashoka dies and the empire begins a rapid decline"],["c. 185 BCE","Pushyamitra Shunga assassinates Brihadratha, ending Maurya rule"]]},
  "Median Empire": {t:["The Median Empire grew from a confederation of Zagros tribes into a leading Near Eastern power ruled from Ecbatana.","Allied with Babylon, the Medes destroyed Assyria, sacking Ashur in 614 BCE and Nineveh in 612 BCE.","Cyrus the Great absorbed it c. 550 BCE, but its nobles and court customs lived on inside the Achaemenid Empire."],dyk:"Median influence on Persia ran so deep that Greek writers often called the Persians 'Medes' and termed collaboration with Persia 'Medism'.",ev:[["c. 700 BCE","Deioces, according to Herodotus, unites the Median clans and founds Ecbatana"],["c. 653 BCE","Phraortes dies and a period of Scythian domination begins"],["c. 625 BCE","Cyaxares restores Median power and reorganises the army"],["614 BCE","The Medes capture Ashur"],["612 BCE","Cyaxares and Nabopolassar of Babylon destroy Nineveh"],["585 BCE","War with Lydia ends after the battle of the eclipse, fixing the Halys River frontier"],["c. 550 BCE","Astyages' army mutinies and hands him to Cyrus, who seizes Ecbatana"]]},
  "Ming Empire": {t:["The Ming dynasty restored Han Chinese rule in 1368 after driving the Mongol Yuan court back to the steppe.","Its examination-based bureaucracy, Zheng He's voyages and global silver trade made it a centre of the early modern world.","Fiscal crisis, famine and rebellion let Li Zicheng take Beijing in 1644, opening the way for the Manchu Qing."],dyk:"The Ming Great Wall seen by visitors today is largely a 16th-century brick-faced work, built after the Zhengtong Emperor was captured by the Oirats at Tumu in 1449.",ev:[["1363","Zhu Yuanzhang defeats Chen Youliang at the naval battle of Lake Poyang"],["1368","Zhu Yuanzhang proclaims the Ming dynasty and his armies take the Yuan capital, Dadu"],["1405","Zheng He's first expedition sets out on voyages that reach East Africa by 1433"],["1420","The Forbidden City is completed in the Yongle Emperor's new capital, Beijing"],["1449","The Oirat Mongols capture the Zhengtong Emperor at Tumu"],["1592–1598","The Ming intervene in Korea against the Japanese invasions"],["1644","Li Zicheng takes Beijing; the Chongzhen Emperor takes his own life and the Qing occupy the city"],["1662","The last Southern Ming loyalist regime comes to an end"]]},
  "Mitanni Empire": {t:["Mitanni was a Late Bronze Age great power in northern Syria, with a Hurrian population and kings bearing Indo-Aryan names.","Famed for chariot warfare, it rivalled and later allied with Egypt, sealing ties through royal marriages and letters.","A murdered king and contested succession let the Hittites and Assyria carve it up; Assyria annexed the remnant by c. 1250 BCE."],dyk:"A Mitanni treaty with the Hittites calls on the gods Mitra, Varuna, Indra and the Nasatyas, some of the earliest evidence for Indo-Aryan languages anywhere.",ev:[["c. 1500 BCE","Barattarna extends Mitanni authority over Aleppo and Alalakh"],["c. 1450 BCE","Shaushtatar sacks Ashur and rules vassals such as Arrapha"],["c. 1340 BCE","Hittite king Suppiluliuma I sacks the capital, Washukanni"],["c. 1330 BCE","The Shattiwaza treaty makes Mitanni a Hittite vassal"],["Mid-13th century BCE","Shalmaneser I of Assyria crushes Shattuara II and annexes Hanigalbat"]]},
  "Mongol Empire": {t:["Genghis Khan united the steppe tribes in 1206 and built the largest contiguous land empire in history.","Under the Pax Mongolica, protected trade routes linked China, the Middle East and Europe as never before.","Succession wars split it into rival khanates after 1260; the Yuan fell to the Ming in 1368."],dyk:"The Mongols generally tolerated diverse faiths, even granting clergy tax exemptions in return for prayers for the khan.",ev:[["1206","Temüjin is proclaimed Genghis Khan at a kurultai on the Mongolian steppe"],["1219–1221","Genghis Khan destroys the Khwarazmian Empire in Central Asia"],["1223","Subutai and Jebe defeat the Rus and Kipchaks at the Kalka River"],["1241","Mongol armies defeat Polish and Hungarian forces at Legnica and Mohi"],["1258","Hülegü sacks Baghdad, ending the Abbasid Caliphate"],["1260–1264","The succession war between Kublai and Ariq Böke splits the empire into khanates"],["1294","Kublai's death removes the last Great Khan widely recognised across the empire"],["1368","The Ming drive the Yuan dynasty out of China"]]},
  "Mughal Empire": {t:["The Mughal Empire was founded by the Timurid prince Babur in 1526 and came to rule most of the Indian subcontinent.","Akbar's cash revenue system, ranked nobility and religious accommodation built one of the largest economies of its age.","Aurangzeb's costly wars, regional revolts and the rise of the East India Company hollowed it out before its end in 1858."],dyk:"Babur descended from Timur on his father's side and from Genghis Khan on his mother's, and his dynasty's name comes from the Persian word for Mongol.",ev:[["1526","Babur defeats Ibrahim Lodi at the First Battle of Panipat and founds the empire"],["1527","Babur defeats the Rajput confederacy of Rana Sanga at Khanwa"],["1555","Humayun recovers Delhi after years of exile under Sher Shah Suri's rule"],["1556","Akbar begins his reign, turning a fragile conquest into a stable empire"],["1564","Akbar abolishes the jizya tax on non-Muslims"],["1687","Aurangzeb annexes Golconda, bringing the empire near its greatest extent"],["1739","Nader Shah of Persia sacks Delhi and carries off the Peacock Throne"],["1858","The British exile Bahadur Shah II, the last emperor, to Rangoon"]]},
  "Mutapa Empire": {t:["The Mutapa Empire was a Shona state between the Zambezi and Limpopo, founded c. 1430 as Great Zimbabwe declined.","Its gold, traded via Swahili merchants at ports such as Sofala, tied the African interior to the Indian Ocean economy.","Succession disputes, Portuguese meddling and the rise of the Rozvi broke its power, though a remnant survived until 1917."],dyk:"In 1561 the Jesuit Gonçalo da Silveira briefly converted the reigning Mwene Mutapa to Christianity, only to be killed at the royal court soon afterwards.",ev:[["c. 1430","Nyatsimba Mutota traditionally founds the state on the northern Zimbabwe plateau"],["1561","Jesuit Gonçalo da Silveira converts the Mwene Mutapa and is then killed at court"],["1571–1573","A large Portuguese expedition under Francisco Barreto fails, largely through disease"],["1607","Gatsi Rusere cedes mining rights to the Portuguese in return for military help"],["1629","The Portuguese depose Kapararidze and install Mavura as a vassal ruler"],["1680s–1690s","The Rozvi under Changamire Dombo supplant Mutapa authority across the plateau"],["1917","The Portuguese suppress the last reduced Mutapa kingdom in the Zambezi valley"]]},
  "Neo-Sumerian Empire": {t:["The Neo-Sumerian Empire, or Third Dynasty of Ur, revived Sumerian rule in southern Mesopotamia after the Akkadian collapse.","Its bureaucracy recorded the economy on tens of thousands of tablets, and its law code is the oldest that survives.","Amorite incursions, grain shortages and breakaway governors weakened it until Elam sacked Ur c. 2004 BCE."],dyk:"The Code of Ur-Nammu, some three centuries older than Hammurabi's, punished many offences with monetary fines rather than physical penalties.",ev:[["c. 2112 BCE","Ur-Nammu founds the Third Dynasty of Ur after Utu-hegal expels the Gutians"],["c. 2094 BCE","Shulgi becomes king and expands and centralises the state"],["c. 2047 BCE","Shulgi's long reign ends; under his successors the empire begins to decline"],["c. 2004 BCE","Elamite forces sack Ur and carry the last king, Ibbi-Sin, into captivity"]]},
  "Ottoman Empire": {t:["The Ottoman Empire grew from a frontier beylik in Anatolia into a power spanning three continents for over six centuries.","Janissary infantry, gunpowder artillery and a sophisticated bureaucracy let it take Constantinople and rule a diverse realm.","Lost wars, nationalist revolts and European debt control eroded it; defeat in the First World War ended the sultanate in 1922."],dyk:"The architect Mimar Sinan is credited with more than three hundred buildings, including the Süleymaniye Mosque in Istanbul and the Selimiye Mosque in Edirne.",ev:[["1302","Osman I defeats a Byzantine force at the Battle of Bapheus"],["1326","Orhan captures Bursa, the dynasty's first true capital"],["1453","Mehmed II captures Constantinople after a siege of some fifty-three days"],["1516–1517","Selim I conquers the Mamluk Sultanate, gaining Egypt, Syria and the holy cities"],["1526","Suleiman the Magnificent destroys the Hungarian royal army at Mohács"],["1683","Jan III Sobieski routs the Ottoman army at the second siege of Vienna"],["1839","The Tanzimat reforms begin to modernise administration and law"],["1922","The Grand National Assembly abolishes the sultanate"]]},
  "Oyo Empire": {t:["The Oyo Empire was a Yoruba savannah state whose cavalry made it the leading power between the Niger and the Volta.","It grew rich on tribute and the Atlantic slave trade, forcing Dahomey into vassalage and shaping the Bight of Benin coast.","Feuds between king and chiefs, Afonja's revolt and the Ilorin emirate destroyed it; Oyo-Ile was abandoned c. 1835–1836."],dyk:"Oyo's council of chiefs could reject an Alaafin by presenting him with an empty calabash or parrots' eggs, after which the king was expected to take his own life.",ev:[["c. 1610","Alaafin Abipa reoccupies Oyo-Ile after some eighty years of exile"],["1726","Oyo begins repeated cavalry invasions of Dahomey"],["1748","A treaty confirms Dahomey as a tribute-paying vassal of Oyo"],["c. 1774","Alaafin Abiodun overthrows and executes Basorun Gaa, who had dominated the state"],["c. 1796","Alaafin Awole is forced to take his own life after his war chiefs mutiny"],["c. 1817","Afonja rebels at Ilorin with Fulani and Hausa support inspired by the Sokoto jihad"],["c. 1835–1836","Oyo-Ile is abandoned; Alaafin Atiba founds a reduced state at New Oyo"],["1888","New Oyo signs a treaty with the British"]]},
  "Parthian Empire": {t:["The Parthian Empire was an Iranian power founded by the Arsacids that ruled from the Euphrates to the Iranian plateau.","Its cavalry held Rome at the Euphrates for centuries, and it profited as the Silk Road link between Rome and Han China.","Noble rivalry, civil wars and Roman captures of Ctesiphon weakened it; Ardashir I's Sasanians ended Arsacid rule in 224 CE."],dyk:"At Carrhae in 53 BCE, the Parthian general Surena kept his horse archers supplied from a camel train of arrows, destroying a Roman army under Crassus.",ev:[["c. 238 BCE","Arsaces I of the Parni seizes the satrapy of Parthia from Andragoras"],["c. 141 BCE","Mithridates I conquers the Seleucid heartland of Mesopotamia"],["53 BCE","Surena's Parthian army destroys the Roman army of Crassus at Carrhae"],["36 BCE","Mark Antony's invasion ends in a costly Roman retreat"],["116","Trajan captures the Parthian capital, Ctesiphon"],["198","Septimius Severus captures Ctesiphon again"],["224","Ardashir I kills Artabanus IV at Hormozdgan, founding the Sasanian Empire"]]},
  "Polish-Lithuanian Commonwealth": {t:["The Commonwealth joined Poland and Lithuania in 1569 into one of Europe's largest states, with an elected king and noble parliament.","Its religious tolerance made it a refuge for dissenters and home to the world's largest Jewish population.","The liberum veto paralysed reform, letting Russia, Prussia and Austria partition it out of existence by 1795."],dyk:"In 1610, after the victory at Klushino, Polish troops occupied Moscow and a group of boyars elected the Polish prince Władysław as Tsar.",ev:[["1569","The Union of Lublin creates the Commonwealth from Poland and Lithuania"],["1573","The Warsaw Confederation guarantees religious peace among the nobility"],["1610","Żółkiewski wins at Klushino and Polish troops occupy Moscow"],["1648","Bohdan Khmelnytsky's Cossack uprising begins in Ukraine"],["1652","Władysław Siciński breaks up the Sejm with a single objection, the first liberum veto"],["1683","Jan III Sobieski leads the cavalry charge that relieves Vienna"],["1791","The Constitution of 3 May abolishes the liberum veto"],["1795","The Third Partition erases the Commonwealth from the map"]]},
  "Portuguese Empire": {t:["Portugal built the first sea-borne trading empire linking Europe, Africa, Asia and the Americas, starting at Ceuta in 1415.","It controlled the spice route around Africa and became the largest national carrier in the Atlantic slave trade.","Dutch rivals, Brazilian independence and colonial wars wore it down; the last territory, Macau, went to China in 1999."],dyk:"Portuguese traders who landed on Tanegashima in 1543 introduced the arquebus to Japan, where gunsmiths quickly copied it and changed Sengoku-era warfare.",ev:[["1415","João I and his sons capture Ceuta, beginning the imperial project"],["1488","Bartolomeu Dias rounds the Cape of Good Hope"],["1498","Vasco da Gama reaches Calicut, opening the sea route to India"],["1500","Pedro Álvares Cabral makes landfall in Brazil"],["1510","Afonso de Albuquerque seizes Goa"],["1578","King Sebastião I is killed at Alcácer Quibir, triggering a succession crisis"],["1822","Brazil declares independence under Pedro I"],["1974","The Carnation Revolution topples the dictatorship and opens the way to African independence"]]},
  "Ptolemaic Empire": {t:["The Ptolemaic Kingdom was a Macedonian dynasty that ruled Egypt as pharaohs from Alexandria for nearly three centuries.","Nile grain made it rich, and Alexandria's Library, Mouseion and Pharos made it the intellectual capital of the Hellenistic world.","Dynastic feuds, native revolts and Roman meddling wore it down; after Actium, Rome annexed Egypt in 30 BCE."],dyk:"The Rosetta Stone, the key to deciphering hieroglyphs, records a Ptolemaic priestly decree of 196 BCE written in hieroglyphic, demotic and Greek.",ev:[["323 BCE","Ptolemy becomes satrap of Egypt after the death of Alexander the Great"],["305 BCE","Ptolemy I Soter proclaims himself king, founding the dynasty"],["283 BCE","Ptolemy II Philadelphus begins his reign over an empire reaching Cyprus and the Aegean"],["217 BCE","Ptolemy IV defeats Antiochus III at Raphia with a phalanx of native Egyptians"],["206–186 BCE","A great native revolt disrupts Upper Egypt"],["196 BCE","Priests issue the decree later inscribed on the Rosetta Stone"],["31 BCE","Octavian defeats Cleopatra VII and Mark Antony at Actium"],["30 BCE","Rome annexes Egypt, ending the Ptolemaic state"]]},
  "Punic Empire": {t:["Carthage, a Phoenician colony of Tyre in Tunisia, built a trading empire across the western Mediterranean.","Its fleets, mercenary armies and Hannibal's invasion of Italy made it Rome's greatest rival for over a century.","Three Punic Wars stripped it of Sicily, Spain and its navy; Rome razed the city in 146 BCE and enslaved its survivors."],dyk:"After destroying Carthage, the Roman Senate ordered the farming treatise of the Carthaginian writer Mago, in twenty-eight books, to be translated into Latin.",ev:[["814 BCE","Elissa (Dido) of Tyre traditionally founds Carthage"],["264–241 BCE","Carthage loses Sicily to Rome in the First Punic War"],["237 BCE","The Barcid family begins the conquest of southern Iberia"],["218 BCE","Hannibal crosses the Alps and invades Italy"],["216 BCE","Hannibal annihilates a Roman army at Cannae"],["202 BCE","Scipio defeats Hannibal at Zama"],["146 BCE","Scipio Aemilianus storms and razes Carthage, ending the Third Punic War"]]},
  "Qing Empire": {t:["The Qing was a Manchu dynasty that conquered Ming China in 1644 and ruled the world's most populous empire.","It reached its greatest extent in the 18th century, setting the territorial framework of modern China.","Rebellion, defeat in the Opium Wars and by Japan, and failed reform led to revolution and Puyi's abdication in 1912."],dyk:"Nurhaci's Banner system organised the entire Jurchen population into colour-coded units that were at once army formations, census registers and social structures.",ev:[["1616","Nurhaci proclaims the Later Jin dynasty"],["1636","Hong Taiji proclaims the Qing dynasty"],["1644","Wu Sangui opens the Shanhai Pass and Qing forces capture Beijing"],["1683","The Qing conquer Taiwan from the Zheng regime, completing consolidation"],["1839–1842","Britain defeats the Qing in the First Opium War, forcing the Treaty of Nanjing"],["1850–1864","The Taiping Rebellion kills an estimated twenty to thirty million people"],["1894–1895","Japan defeats the Qing in the First Sino-Japanese War"],["1912","The six-year-old Puyi abdicates, ending imperial rule in China"]]},
  "Rashidun Caliphate": {t:["The Rashidun Caliphate was the rule of the first four caliphs after the Prophet Muhammad, from Medina, in 632–661.","In about 25 years it destroyed the Sasanian Empire and took Syria and Egypt from Byzantium, setting Arabic on its path to dominance.","Disputes over succession led to the murders of three caliphs and civil war, ending in the hereditary Umayyad Caliphate."],dyk:"Umar adopted the Islamic lunar calendar for official dating, anchoring it to the hijra of 622, the system still used in the Muslim world today.",ev:[["632","Abu Bakr is acclaimed first caliph after Muhammad's death and launches the Ridda Wars"],["634","Umar ibn al-Khattab succeeds Abu Bakr and accelerates the conquests"],["636","Khalid ibn al-Walid and Abu Ubayda defeat the Byzantines at the Yarmuk"],["640–642","Amr ibn al-As conquers Egypt"],["642","Victory at Nihawand breaks the last organised Sasanian field army"],["656","Rebels assassinate Uthman, triggering the First Fitna"],["657","Ali and Muawiya fight the inconclusive Battle of Siffin"],["661","Ibn Muljam assassinates Ali at Kufa; the Umayyad Caliphate follows"]]},
  "Roman Empire": {t:["Augustus turned the war-torn Roman Republic into a monarchy in 27 BCE while keeping the Senate and consuls as a republican facade.","Its professional legions, 80,000 km of roads and Roman law bound a realm stretching from Britain to Mesopotamia.","The West fell gradually through civil war, Gothic and Vandal invasions and lost revenues, ending when Odoacer deposed Romulus Augustulus in 476."],dyk:"When Odoacer deposed the last Western emperor in 476, he simply sent the imperial regalia to Constantinople, and contemporaries barely remarked on it.",ev:[["31 BCE","Octavian defeats Mark Antony and Cleopatra VII at the Battle of Actium"],["27 BCE","The Senate grants Octavian the title Augustus, making him Rome's first emperor"],["9","Arminius destroys three legions under Varus in the Teutoburg Forest, fixing the Rhine frontier"],["212","The Edict of Caracalla extends citizenship to virtually all free inhabitants of the empire"],["313","Constantine and Licinius agree the Edict of Milan, ending the persecution of Christians"],["378","Gothic forces kill Emperor Valens and much of the Eastern field army at Adrianople"],["410","Alaric's Visigoths sack Rome, shattering the myth of Roman invulnerability"],["476","Odoacer deposes Romulus Augustulus, the last Western Roman emperor"]]},
  "Rozvi Empire": {t:["Founded by the former herdsman Changamire Dombo I, the Rozvi Empire dominated the Zimbabwean plateau from the late 17th century.","Dombo drove Portuguese traders and settlers from the interior in the 1690s, keeping the gold and ivory trade under African control.","Drought, a shift in coastal demand and Nguni invasions of the Mfecane destroyed the state in the 1830s; its stone ruins and Mwari cult endured."],dyk:"The Mwari cult patronised by the Rozvi outlived the empire and helped organise resistance to British South Africa Company rule in 1896-1897.",ev:[["c. 1670s","Changamire Dombo builds a power base in Guruuswa under the Mutapa ruler Mukombwe"],["1684","Dombo defeats Mutapa and Portuguese forces at the Battle of Maungwe"],["1693","Rozvi forces destroy the Portuguese settlement at Dambarare and sweep away the interior fairs"],["1695","The Portuguese fair at Masekesa in Manica falls, shortly before Dombo's death"],["c. 1810s","The rise of Shaka's Zulu kingdom sets off the Mfecane, displacing Nguni groups northwards"],["c. 1830s","Zwangendaba's Ngoni cross the plateau; Nyamazana's forces later kill the reigning Changamire"],["c. 1840","Mzilikazi's Ndebele occupy the former Rozvi heartland"]]},
  "Russian Empire": {t:["Proclaimed by Peter the Great in 1721 after defeating Sweden, the Russian Empire grew to cover some 22.8 million square kilometres.","It spread Russian rule from the Baltic to the Pacific and Central Asia, and freed some 23 million serfs in 1861.","Autocracy, rural discontent and the strain of the First World War brought revolution and Nicholas II's abdication in 1917."],dyk:"Before the Battle of Tsushima in 1905, Russia's Baltic Fleet sailed some 18,000 nautical miles around the world, only to be annihilated by Japan.",ev:[["1703","Peter I begins building Saint Petersburg on conquered Swedish territory"],["1709","Peter's reformed army defeats Charles XII of Sweden at Poltava"],["1721","The Senate proclaims Peter I Emperor of All Russia after the Treaty of Nystad"],["1812","Napoleon's Grande Armée invades Russia and is destroyed in the winter retreat"],["1861","Alexander II's Emancipation Edict frees some 23 million privately owned serfs"],["1891","Construction of the Trans-Siberian Railway begins"],["1905","Defeat at Tsushima and revolution force Nicholas II to issue the October Manifesto"],["1917","Nicholas II abdicates after the Petrograd garrison mutinies"]]},
  "Safavid Empire": {t:["Founded in 1501 by the Sufi leader Ismail I, the Safavid Empire reunited Iran for the first time since the Mongol Ilkhanate.","By imposing Twelver Shia Islam it gave Iran its lasting religious identity and turned the Sunni-Shia divide into a frontier with the Ottomans.","Weak harem-raised shahs and religious intolerance left it open to an Afghan revolt; Isfahan fell in 1722 and the dynasty ended in 1736."],dyk:"After surrendering Isfahan in 1722, Shah Sultan Husayn personally placed the crown on the head of the Afghan conqueror Mir Mahmud Hotak.",ev:[["1501","Ismail I defeats the Aq Qoyunlu, seizes Tabriz and proclaims Twelver Shiism the state religion"],["1514","Selim I's Ottoman guns and janissaries rout the Qizilbash cavalry at Chaldiran"],["1598","Shah Abbas I's reformed army recovers Herat and Khorasan from the Uzbeks"],["1604","Abbas I begins moving the Armenian merchants of Julfa to New Julfa beside Isfahan"],["1622","Abbas I expels the Portuguese from Hormuz with English naval help"],["1639","The Treaty of Zuhab fixes a Safavid-Ottoman frontier close to today's Iran-Iraq border"],["1722","Mir Mahmud Hotak wins at Gulnabad and takes Isfahan after a seven-month siege"],["1736","Nader Quli Afshar is proclaimed Shah on the Mughan plain, ending the Safavid dynasty"]]},
  "Sasanian Empire": {t:["The Sasanian Empire ruled Iran and Mesopotamia from 224 to 651, a centralised Zoroastrian monarchy that was Rome's great rival for four centuries.","Its armoured cavalry, fixed land tax and court culture shaped Byzantium and, above all, the Islamic caliphates that followed.","A ruinous war with Byzantium and a succession crisis left it defenceless against the Arab conquests that ended it by 651."],dyk:"Shapur I captured the Roman emperor Valerian at Edessa in 260, the only time a reigning Roman emperor was taken prisoner by a foreign power.",ev:[["224","Ardashir I defeats and kills the last Parthian king, Artabanus IV, at Hormozdgan"],["260","Shapur I captures the Roman emperor Valerian at the Battle of Edessa"],["363","Shapur II wins Nisibis and lands beyond the Tigris in a peace with Rome's Jovian"],["c. 557","Khosrow I and the Göktürks begin destroying the Hephthalite empire"],["614","Khosrow II's general Shahrbaraz captures Jerusalem"],["627","Heraclius defeats the Sasanians at the Battle of Nineveh"],["c. 636","Arab armies destroy the main Sasanian field army at al-Qadisiyyah"],["651","The last king, Yazdegerd III, is murdered near Merv"]]},
  "Seleucid Empire": {t:["Carved out of Alexander's conquests by his general Seleucus I, the Seleucid Empire stretched from Syria towards India at its height.","Its many new Greek cities spread Hellenistic language and culture across the Near East and Central Asia for centuries.","Defeat by Rome, Parthian conquest of the east and endless dynastic civil war reduced it to a Syrian rump that Pompey annexed in 64-63 BCE."],dyk:"Seleucus I traded eastern lands to Chandragupta Maurya for 500 war elephants, which helped him win the Battle of Ipsus in 301 BCE.",ev:[["312 BCE","Seleucus retakes Babylon after the Battle of Gaza, the starting point of the Seleucid era"],["301 BCE","Seleucus and Lysimachus defeat and kill Antigonus at the Battle of Ipsus"],["281 BCE","Seleucus defeats Lysimachus at Corupedium but is assassinated within months"],["212 BCE","Antiochus III begins a seven-year eastern campaign that earns him the title 'the Great'"],["190 BCE","Rome routs Antiochus III's army at the Battle of Magnesia"],["167 BCE","Antiochus IV's suppression of Jewish practice sparks the Maccabean revolt"],["141 BCE","Mithridates I of Parthia conquers Mesopotamia and captures Seleucia-on-Tigris"],["64 BCE","Pompey deposes Antiochus XIII and makes Syria a Roman province"]]},
  "Seljuk Empire": {t:["Oghuz Turks from the Central Asian steppe, the Seljuks built an empire from Khorasan to the Mediterranean and became protectors of Sunni Islam.","Their victory at Manzikert opened Anatolia to Turkish settlement, paving the way for the Ottomans and helping provoke the Crusades.","With no fixed succession, the empire splintered after 1092; Qara Khitai and Khwarazmian blows ended the Great Seljuk line by 1194."],dyk:"The poet and mathematician Omar Khayyam worked under Seljuk patronage on the Jalali solar calendar of 1079, more accurate than the Julian calendar.",ev:[["1037","Tughril and Chaghri take Merv and Nishapur, throwing off Ghaznavid authority"],["1040","Tughril and Chaghri rout the Ghaznavid sultan Masud I at Dandanaqan"],["1055","Tughril enters Baghdad and is recognised as sultan by the Abbasid caliph"],["1071","Alp Arslan defeats and captures the Byzantine emperor Romanos IV at Manzikert"],["1092","Vizier Nizam al-Mulk is assassinated and Malik Shah dies weeks later, sparking civil war"],["1141","The Qara Khitai defeat Sultan Sanjar at the Battle of Qatwan"],["1157","Sanjar's death ends the eastern Seljuk line"],["1194","The Khwarazm Shah Tekish kills Toghrul III, extinguishing the Great Seljuks"]]},
  "Sikh Empire": {t:["Maharaja Ranjit Singh united the feuding Sikh Misls into a single Punjab state, ruling from Lahore from 1799.","Its European-drilled army was among the strongest in India, and it governed a Muslim-majority population with a mixed-faith court.","Without institutions to manage succession, it collapsed into court intrigue after 1839 and was annexed by Britain in 1849."],dyk:"Ranjit Singh had the upper storeys of the Harmandir Sahib covered in gilded copper, giving it its popular name: the Golden Temple.",ev:[["1799","Ranjit Singh, aged eighteen, seizes Lahore from its Bhangi chiefs"],["1801","Ranjit Singh is proclaimed Maharaja of the Punjab on Baisakhi"],["1809","The Treaty of Amritsar fixes the Sutlej as the Sikh-British boundary"],["1819","Sikh forces conquer Kashmir"],["1834","The Sikhs occupy Peshawar, extending the empire to the Khyber Pass"],["1839","Ranjit Singh dies, leaving the Lahore court to rival factions"],["1846","Defeat at Sobraon ends the First Anglo-Sikh War; Kashmir is lost"],["1849","Lord Dalhousie annexes the Punjab after the Second Anglo-Sikh War"]]},
  "Sokoto Caliphate": {t:["Born of Usman dan Fodio's Islamic reform jihad of 1804, the Sokoto Caliphate became the largest state in 19th-century West Africa.","Some thirty emirates shared one Islamic legal culture, a decentralised design that survived for almost a century without succession crises.","British forces with Maxim guns conquered it in 1903, then governed northern Nigeria through its emirs under indirect rule."],dyk:"The last independent Sultan, Attahiru I, answered the British conquest with a hijra eastwards that deliberately echoed dan Fodio's founding migration.",ev:[["1804","Usman dan Fodio makes his hijra to Gudu and declares jihad against the Hausa kings"],["1808","Jihad forces storm Alkalawa, the Gobir capital, killing Sultan Yunfa"],["1817","Dan Fodio dies; his son Muhammad Bello becomes Sultan of Sokoto"],["1886","Britain charters the Royal Niger Company"],["1900","Frederick Lugard proclaims the Protectorate of Northern Nigeria"],["1903","British forces take Kano in February and occupy Sokoto in March"],["1903","Sultan Attahiru I is killed fighting the British at Burmi in July"]]},
  "Song Dynasty": {t:["The Song Dynasty ruled China from 960 to 1279, governed by exam-selected scholar-officials rather than generals.","It ran the world's most commercial economy, with paper money and huge cities, and developed gunpowder weapons, the compass and movable type.","Lacking warhorses and cavalry, it lost the north to the Jurchen in 1127 and fell to Kublai Khan's Mongols after four decades of resistance."],dyk:"Bi Sheng invented movable type using ceramic characters around 1040, some four centuries before Gutenberg's printing press.",ev:[["960","Zhao Kuangyin seizes power in the Chenqiao Mutiny and founds the Song Dynasty"],["1005","The Chanyuan Treaty commits the Song to annual silk and silver payments to the Liao"],["1069","Wang Anshi launches the New Policies to reform state finances"],["1127","The Jurchen Jin capture Kaifeng and carry off emperors Huizong and Qinzong"],["1161","Southern Song fleets defeat the Jin at Tangdao and Caishi"],["1268","The Mongols begin the five-year siege of Xiangyang"],["1276","Lin'an surrenders and the boy emperor Gong is taken north"],["1279","The loyalist fleet is destroyed at Yamen, ending the Song Dynasty"]]},
  "Songhai Empire": {t:["The largest empire in West African history, Songhai controlled the Niger Bend and its trade cities of Gao, Timbuktu and Djenné.","Its wealth came from the trans-Saharan gold and salt trade, and its patronage made Timbuktu a centre of Islamic scholarship.","Weakened by civil war, it was shattered in 1591 by a small Moroccan army whose firearms routed a far larger Songhai force at Tondibi."],dyk:"The traveller Leo Africanus, visiting Timbuktu around 1510, reported that books were sold there at greater profit than any other merchandise.",ev:[["1464","Sunni Ali begins his reign and launches campaigns of conquest"],["1468","Sunni Ali takes Timbuktu from the Tuareg"],["c. 1473","Djenné submits to Songhai after a long siege"],["1493","Muhammad Ture defeats Sunni Baru and takes the title Askia"],["1496","Askia Muhammad sets out on his pilgrimage to Mecca"],["1528","Askia Muhammad is deposed by his son Askia Musa"],["1588","Civil war divides the Songhai Empire"],["1591","Judar Pasha's Moroccan army routs Askia Ishaq II at the Battle of Tondibi"]]},
  "Spanish Empire": {t:["Often called the first global empire, Spain ruled lands across Europe, the Americas, Africa and Asia from the 1490s.","American silver from mines like Potosí reshaped world money, and the Columbian Exchange transformed diets, populations and faiths.","Costly wars and bankruptcies eroded its power; the American colonies broke away by 1826 and the last major ones were lost in 1898."],dyk:"From 1565 to 1815 the Manila Galleon linked Acapulco and Manila, the first sustained direct trade link between the Americas and Asia.",ev:[["1492","Granada falls, ending the Reconquista, and Columbus sails west for Castile"],["1494","The Treaty of Tordesillas divides the world between Spain and Portugal"],["1519","Hernán Cortés begins the conquest of the Aztec Empire, completed in 1521"],["1532","Francisco Pizarro begins the conquest of the Inca Empire"],["1580","Philip II unites the crowns of Spain and Portugal"],["1588","The Spanish Armada sent against England is defeated and wrecked by storms"],["1648","The Peace of Westphalia confirms Dutch independence from Spain"],["1898","Defeat by the United States strips Spain of Cuba, Puerto Rico and the Philippines"]]},
  "Srivijaya Empire": {t:["Based at Palembang in Sumatra, Srivijaya was a sea power that ruled the Strait of Malacca from the 7th to the 13th century.","It grew rich by taxing China-India shipping and became a renowned centre of Buddhist learning, spreading Old Malay across the region.","Chola raids, Javanese rivals, direct Chinese shipping and the spread of Islam wore it down until Temasek and Malacca took its role."],dyk:"The Chinese pilgrim Yijing, who stopped there in 671, found over a thousand Buddhist monks and advised Chinese monks to study in Srivijaya before going to India.",ev:[["671","The Chinese pilgrim Yijing visits Srivijaya on his way to India"],["682","The Kedukan Bukit inscription records Sri Jayanasa's military expedition"],["c. 990","Srivijaya withstands an attack on Sumatra by Dharmawangsa of Medang"],["1016","The Medang court in Java is destroyed by the rebellion of the ruler of Wurawari"],["1025","Rajendra Chola I sacks Srivijaya and its ports and captures its ruler"],["c. 1068","A further Chola naval expedition under Virarajendra strikes the region"],["1275","Kertanagara of Singhasari launches the Pamalayu expedition against Malayu"]]},
  "Swedish Empire": {t:["In the 17th century a poor kingdom of some 2.5 million people made itself the dominant power of the Baltic.","Gustavus Adolphus's military reforms reshaped European warfare and his intervention changed the course of the Thirty Years War.","Charles XII's defeat by Russia at Poltava in 1709 broke Swedish power, and the Peace of Nystad in 1721 ended the empire."],dyk:"Stockholms Banco issued Europe's first banknotes in 1661, and its successor, the Sveriges Riksbank of 1668, is the oldest central bank still operating.",ev:[["1617","The Peace of Stolbovo gives Sweden Ingria and Kexholm from Russia"],["1630","Gustavus Adolphus intervenes in the Thirty Years War"],["1631","Swedish and Saxon forces rout Tilly's Catholic League army at Breitenfeld"],["1648","The Peace of Westphalia grants Sweden Western Pomerania, Bremen, Verden and Wismar"],["1658","Charles X Gustav marches across the frozen Belts and forces the Treaty of Roskilde on Denmark"],["1709","Peter the Great crushes Charles XII's army at Poltava"],["1718","Charles XII is killed at the siege of Fredriksten in Norway"],["1721","The Peace of Nystad cedes Estonia, Livonia and Ingria to Russia"]]},
  "Tang Dynasty": {t:["Founded in 618, the Tang Dynasty pushed Chinese power deep into Central Asia and made Chang'an one of the world's great cities.","Its law code, government model and Buddhist culture were adopted by Japan, Korea and Vietnam and shaped East Asia for centuries.","The An Lushan Rebellion left power with regional generals; the Huang Chao uprising finished it and a warlord deposed the last emperor in 907."],dyk:"The Diamond Sutra of 868, found at Dunhuang, is the oldest surviving dated printed book in the world.",ev:[["618","Li Yuan proclaims the Tang Dynasty after seizing Chang'an from the collapsing Sui"],["626","Li Shimin kills his brothers at the Xuanwu Gate and becomes Emperor Taizong"],["630","The Tang destroy the Eastern Turkic Khaganate; Taizong is hailed as Heavenly Khagan"],["690","Wu Zetian proclaims her own Zhou dynasty, interrupting Tang rule until 705"],["751","Abbasid forces defeat Gao Xianzhi's Tang army at the Battle of Talas"],["755","An Lushan rebels, capturing Luoyang and Chang'an and forcing Xuanzong to flee"],["881","Huang Chao's rebels sack Chang'an"],["907","Zhu Wen deposes the last Tang emperor and founds the Later Liang"]]},
  "Timurid Empire": {t:["Timur, a Barlas noble from Transoxiana, carved out an empire from Anatolia to the borders of China by conquest and calculated terror.","His heirs turned Samarkand and Herat into brilliant centres of painting, poetry and astronomy that shaped Safavid and Mughal culture.","Built on one man's authority, it split among feuding princes after 1405 and fell to the Uzbeks, but Babur carried its legacy to Mughal India."],dyk:"Ulugh Beg's Samarkand star catalogue of over a thousand stars was among the most accurate before the telescope, and was published at Oxford in 1665.",ev:[["1387","Timur's army raises towers of skulls from the population of Isfahan"],["1395","Timur defeats Tokhtamysh of the Golden Horde on the Terek"],["1398","Timur sacks Delhi, leaving the city devastated for decades"],["1402","Timur defeats and captures the Ottoman Sultan Bayezid I at Ankara"],["1405","Timur dies at Otrar while marching to invade Ming China"],["1449","Ulugh Beg is put to death at the instigation of his own son"],["1469","Abu Sa'id, last Timurid to reunite much of the realm, is killed fighting the Aq Qoyunlu"],["1507","Muhammad Shaybani Khan takes Herat, ending Timurid rule"]]},
  "Tokugawa Shogunate": {t:["After victory at Sekigahara, the Tokugawa shoguns ruled Japan from Edo from 1603 to 1868, keeping some 260 daimyo in check.","Two and a half centuries of peace fostered a commercial economy, a city of a million in Edo, and arts like kabuki and ukiyo-e.","Unable to resist Perry's 'Black Ships' or the rising domains of Satsuma and Choshu, the last shogun handed power back to the emperor in 1867."],dyk:"After the Shimabara Rebellion of 1637-1638, Japan under the Tokugawa saw no major warfare for more than two centuries.",ev:[["1600","Tokugawa Ieyasu defeats Ishida Mitsunari's western coalition at Sekigahara"],["1603","The imperial court appoints Ieyasu shogun"],["1615","The siege of Osaka Castle destroys the Toyotomi house"],["1635","Iemitsu formalises sankin-kotai, the alternate attendance of daimyo in Edo"],["1641","Dutch traders are confined to the artificial island of Dejima in Nagasaki"],["1853","Commodore Perry's 'Black Ships' enter Edo Bay demanding open ports"],["1867","Shogun Tokugawa Yoshinobu returns governing authority to Emperor Meiji"],["1868","Imperial rule is restored and the Boshin War begins at Toba-Fushimi"]]},
  "Umayyad Caliphate": {t:["The Umayyads turned the caliphate into a hereditary monarchy ruled from Damascus, from 661 to 750.","Their conquests reached from Spain to Sind and Central Asia, spreading Arabic and laying the ground for Islam across three continents.","Favouring Arabs over non-Arab converts bred revolt; the Abbasids overthrew them in 750, though a survivor founded a new Umayyad state in Spain."],dyk:"Abd al-Malik's gold dinar of 697 dropped Byzantine and Persian imagery for Arabic Quranic inscriptions, creating a distinctly Islamic coinage.",ev:[["661","Muawiyah secures the caliphate after Ali's assassination and rules from Damascus"],["680","Husayn ibn Ali is killed at Karbala, the defining martyrdom of Shia Islam"],["c. 691","Abd al-Malik completes the Dome of the Rock in Jerusalem"],["711","Tariq ibn Ziyad crosses into Spain and overthrows the Visigothic kingdom"],["717","The second Arab siege of Constantinople begins and fails the following year"],["732","Charles Martel checks Umayyad raids at the Battle of Tours"],["747","Abu Muslim proclaims the Abbasid Revolution in Khorasan"],["750","Marwan II is defeated at the Great Zab and killed, ending Umayyad rule in the east"]]},
  "Wadai Empire": {t:["Wadai was an Islamic sultanate in what is now eastern Chad, founded in the early 17th century after a revolt against the Tunjur.","Its caravan road to Benghazi made it a major trans-Saharan trading power, fed largely by slave raiding into the lands to the south.","Weakened by succession wars, it fell to the French, who took Abéché in 1909 and abolished the sultanate in 1912."],dyk:"The Anglo-French convention of 1899 assigned Wadai to France and Darfur to Britain, a division that still broadly underlies the Chad-Sudan border.",ev:[["c. 1611","Abd al-Karim ibn Jama overthrows the Tunjur and founds the Wadai sultanate at Wara"],["c. 1803","Sultan Sabun begins his reign and opens a caravan route through Kufra to Benghazi"],["c. 1850","Sultan Muhammad al-Sharif moves the capital from Wara to Abéché"],["1871","Sultan Ali's armies sack Massenya, capital of the rival sultanate of Bagirmi"],["1899","An Anglo-French convention places Wadai in the French sphere"],["1909","A French column captures Abéché and installs Adam Asil as a client sultan"],["1911","Sultan Dud Murra surrenders after years of resistance from the countryside"],["1912","France abolishes the Wadai sultanate"]]},
  "Xiongnu Empire": {t:["The first great steppe empire of eastern Eurasia, the Xiongnu confederation dominated Mongolia from about 209 BCE.","For decades it forced Han China to pay tribute in silk and princesses; its decimal army and court became the model for later steppe empires.","Han campaigns, natural disasters and rival chanyu split it in 48 CE; the Northern Xiongnu vanished as a power around 91 CE."],dyk:"In 200 BCE the Xiongnu trapped the Han founder, Emperor Gaozu, for seven days at Baideng; he escaped only after his envoys bribed the chanyu's consort.",ev:[["209 BCE","Modu seizes power from his father Touman and unites the Xiongnu"],["200 BCE","Modu surrounds Han Emperor Gaozu for seven days at the Battle of Baideng"],["198 BCE","The Han accept the heqin treaty of gifts and royal brides in exchange for peace"],["133 BCE","A failed Han ambush at Mayi ends the policy of appeasement"],["119 BCE","Wei Qing and Huo Qubing defeat the Xiongnu at the Battle of Mobei"],["51 BCE","Chanyu Huhanye travels to Chang'an and acknowledges Han overlordship"],["48","The confederation splits into Southern and Northern Xiongnu"],["89","The Northern Xiongnu suffer a crushing defeat by Han forces and their allies"]]},
  "Yuan Dynasty": {t:["Kublai Khan proclaimed the Yuan Dynasty in 1271, making China the centre of the Mongol world and ruling it from Dadu (Beijing).","It linked China to Persia and Europe across the Mongol network, and its rigid ethnic hierarchy put southern Chinese at the bottom.","Floods, epidemics, runaway paper-money inflation and the Red Turban Rebellion brought it down; the Ming took Dadu in 1368."],dyk:"Kublai's Tibetan preceptor Phagpa devised a new script in 1269 to write all the empire's languages; it appeared on seals and coins but never caught on.",ev:[["1260","Kublai's claim to be Great Khan sparks civil war with his brother Ariq Böke"],["1271","Kublai Khan adopts the dynastic name Da Yuan"],["1273","Xiangyang falls to Mongol counterweight trebuchets after a five-year siege"],["1274","The first Mongol invasion of Japan is wrecked by storms"],["1279","The last Song loyalist fleet is destroyed at Yamen, leaving the Yuan masters of all China"],["1344","The Yellow River bursts its dykes, devastating the North China Plain"],["1351","The Red Turban Rebellion breaks out across the Huai and Yangtze valleys"],["1368","Zhu Yuanzhang proclaims the Ming and Toghon Temür flees Dadu"]]},
  "Zand Empire": {t:["Karim Khan Zand restored order to most of Iran after Nader Shah's murder, ruling from Shiraz without ever taking the title of shah.","His mild rule revived trade and farming and left Shiraz its Vakil bazaar, mosque and bath, still among Iran's finest 18th-century buildings.","After his death in 1779 his relatives fought for the throne, and the Qajar Agha Mohammad Khan destroyed the dynasty by 1794."],dyk:"Karim Khan called himself Vakil al-Ruaya, Deputy of the People, rather than shah, and kept a Safavid prince as nominal sovereign.",ev:[["1747","Nader Shah's assassination leaves Iran in a power vacuum"],["c. 1750","Karim Khan Zand and Ali Mardan Khan install the puppet Shah Ismail III"],["1763","Karim Khan lets the British East India Company open a factory at Bushehr"],["1773","Karim Khan restores the tomb of the poet Hafez in Shiraz"],["1776","Sadeq Khan's forces capture Basra from the Ottomans after a long siege"],["1779","Karim Khan dies, opening fifteen years of Zand civil war"],["1791","Shiraz's governor betrays the city to the Qajars"],["1794","Agha Mohammad Khan takes Kerman and executes the last Zand ruler, Lotf Ali Khan"]]}
};
